values
    ('70000000-0000-4000-8000-000000000001'::uuid, '60000000-0000-4000-8000-000000000001'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 1, 'Which statement best summarizes the discussion of coastal fog?', '[{"id":"A","text":"How coastal trees capture fog and redistribute its water"},{"id":"B","text":"Why coastal rainfall has increased in recent years"},{"id":"C","text":"How redwood roots prevent all water loss"},{"id":"D","text":"Why fog is dangerous to small forest animals"}]'::jsonb, 'A', 'El texto explica el mecanismo de captura de niebla y sus beneficios para distintas partes del ecosistema.', '{"paragraph":2,"quote":"The trees therefore act as structures that redistribute atmospheric water through the ecosystem."}'::jsonb, '{"B":"El texto señala que la lluvia estival es escasa, no que haya aumentado.","C":"Las raíces aprovechan humedad, pero no evitan toda pérdida de agua.","D":"Los animales aparecen como beneficiarios de la humedad, no como víctimas de la niebla."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000002'::uuid, '60000000-0000-4000-8000-000000000001'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'According to the passage, what happens to water that is not absorbed directly by the leaves?', '[{"id":"A","text":"It immediately returns to the ocean."},{"id":"B","text":"It forms larger drops that fall to the ground."},{"id":"C","text":"It remains permanently suspended in the air."},{"id":"D","text":"It is stored inside the tree trunk."}]'::jsonb, 'B', 'El primer párrafo distingue entre la absorción directa y el agua que se agrupa en gotas y cae.', '{"paragraph":1,"quote":"the rest gathers into larger drops that fall to the forest floor"}'::jsonb, '{"A":"No se describe un retorno inmediato al océano.","C":"Las gotas dejan de permanecer suspendidas cuando se agrupan.","D":"El tronco no se menciona como depósito de esa agua."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000003'::uuid, '60000000-0000-4000-8000-000000000001'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 3, 1, 'The phrase “This process” in paragraph 2 refers to', '[{"id":"A","text":"the measurement of rainfall in open areas"},{"id":"B","text":"the growth of shallow roots beneath moss"},{"id":"C","text":"the collection and dripping of water from fog"},{"id":"D","text":"the arrival of summer storms on the coast"}]'::jsonb, 'C', 'La expresión retoma la secuencia descrita justo antes: las hojas interceptan gotas y parte del agua cae al suelo.', '{"paragraph":2,"quote":"This process, known as fog drip"}'::jsonb, '{"A":"Las mediciones aparecen después y no anteceden al demostrativo.","B":"Las raíces absorben el resultado del proceso, pero no lo constituyen.","D":"El texto destaca precisamente la escasez de lluvia estival."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000004'::uuid, '60000000-0000-4000-8000-000000000001'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'What can be inferred about open areas near redwood forests?', '[{"id":"A","text":"Their soil is always deeper than forest soil."},{"id":"B","text":"They receive more summer rainfall than the forest."},{"id":"C","text":"They contain no plants capable of using fog water."},{"id":"D","text":"Their soil may receive less moisture from fog."}]'::jsonb, 'D', 'Si el suelo bajo los redwoods es notablemente más húmedo que el de áreas abiertas cercanas, estas reciben menos aporte por goteo de niebla.', '{"paragraph":2,"quote":"wetter soil beneath redwoods than in nearby open areas"}'::jsonb, '{"A":"La profundidad del suelo nunca se compara.","B":"Las áreas son cercanas y no se afirma que reciban lluvias distintas.","C":"La comparación no permite concluir que carezcan por completo de plantas adaptadas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000005'::uuid, '60000000-0000-4000-8000-000000000001'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 5, 1, 'The word “stress” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"weaken"},{"id":"B","text":"measure"},{"id":"C","text":"surround"},{"id":"D","text":"cool"}]'::jsonb, 'A', 'En este contexto, la falta prolongada de agua puede debilitar al bosque.', '{"paragraph":3,"quote":"can still stress the forest"}'::jsonb, '{"B":"Medir es una acción de los investigadores, no el efecto de la sequía.","C":"Rodear no expresa daño fisiológico.","D":"Enfriar no corresponde al efecto de carecer de lluvia y niebla."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000006'::uuid, '60000000-0000-4000-8000-000000000002'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 1, 'Why does the author discuss fungi and insects in paragraph 1?', '[{"id":"A","text":"To argue that insects are the main cause of tree falls"},{"id":"B","text":"To explain how a fallen trunk becomes suitable for new growth"},{"id":"C","text":"To compare two methods of measuring rainfall"},{"id":"D","text":"To show why young trees must avoid all fungi"}]'::jsonb, 'B', 'Los organismos descomponedores vuelven la madera blanda, porosa y capaz de retener agua, preparando el soporte para plántulas.', '{"paragraph":1,"quote":"breaking its tissues into smaller components"}'::jsonb, '{"A":"El árbol ya está caído cuando llegan los insectos.","C":"No se comparan métodos de medición.","D":"El texto presenta la descomposición como beneficiosa para el establecimiento de plantas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000007'::uuid, '60000000-0000-4000-8000-000000000002'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'Which advantage of growing on a nurse log is mentioned in paragraph 2?', '[{"id":"A","text":"Seedlings no longer need sunlight."},{"id":"B","text":"Their roots immediately reach deep soil."},{"id":"C","text":"Seedlings are lifted above layers of wet leaves."},{"id":"D","text":"They are protected from every forest insect."}]'::jsonb, 'C', 'El segundo párrafo enumera acceso a luz, elevación sobre hojas húmedas y nutrientes liberados por la madera.', '{"paragraph":2,"quote":"keeps them above layers of wet leaves"}'::jsonb, '{"A":"El acceso a la luz es una ventaja, por lo que sí la necesitan.","B":"Las raíces alcanzan el suelo posteriormente, no de inmediato.","D":"No se promete protección total frente a insectos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000008'::uuid, '60000000-0000-4000-8000-000000000002'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 1, 'The word “porous” in paragraph 1 is closest in meaning to', '[{"id":"A","text":"covered by a hard waterproof layer"},{"id":"B","text":"perfectly smooth and dry"},{"id":"C","text":"separated from the forest floor"},{"id":"D","text":"full of small spaces that can hold liquid"}]'::jsonb, 'D', 'La consecuencia inmediata —retener mucha lluvia— aclara que la madera porosa contiene espacios donde entra el agua.', '{"paragraph":1,"quote":"soft and porous, so it can hold considerable amounts of rainwater"}'::jsonb, '{"A":"Una capa impermeable impediría retener agua dentro de la madera.","B":"La madera se describe como húmeda y en descomposición.","C":"La elevación pertenece a la posición del tronco, no al significado de «porous»."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000009'::uuid, '60000000-0000-4000-8000-000000000002'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'How might a person identify the former location of a nurse log many years later?', '[{"id":"A","text":"By looking for a line of trees with elevated roots"},{"id":"B","text":"By finding an undecayed trunk beneath every tree"},{"id":"C","text":"By measuring unusually low rainfall nearby"},{"id":"D","text":"By searching for leaves that receive no light"}]'::jsonb, 'A', 'Aunque el tronco desaparezca, el texto indica que una fila de árboles y sus raíces levantadas conservan la huella de su ubicación.', '{"paragraph":3,"quote":"leaving a row of mature trees whose raised roots reveal where their temporary support once lay"}'::jsonb, '{"B":"El tronco puede haber desaparecido por completo.","C":"La lluvia no funciona como marcador histórico en el pasaje.","D":"La disponibilidad de luz explica el crecimiento, pero no localiza el tronco décadas después."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000010'::uuid, '60000000-0000-4000-8000-000000000002'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 1, 5, 1, 'How is the passage organized?', '[{"id":"A","text":"It presents competing theories about why trees fall."},{"id":"B","text":"It follows the transformation of a fallen tree and its effects over time."},{"id":"C","text":"It classifies forests according to annual rainfall."},{"id":"D","text":"It gives instructions for moving seedlings onto logs."}]'::jsonb, 'B', 'Los párrafos avanzan desde la caída y descomposición hasta el establecimiento de plántulas y la desaparición final del tronco.', '{"paragraph":3,"quote":"The relationship changes over time."}'::jsonb, '{"A":"No aparecen teorías rivales sobre la caída.","C":"La lluvia es parte del proceso, pero no se clasifican bosques.","D":"El texto describe un fenómeno natural, no un procedimiento humano."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000011'::uuid, '60000000-0000-4000-8000-000000000003'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'What is the main idea of the passage?', '[{"id":"A","text":"Most deep-sea light comes from damaged research equipment."},{"id":"B","text":"Bioluminescence is mainly a source of heat for ocean animals."},{"id":"C","text":"Deep-sea organisms use self-produced light in several adaptive ways."},{"id":"D","text":"Only predatory fish are capable of producing light."}]'::jsonb, 'C', 'El texto describe el mecanismo de luz biológica y una variedad de funciones: defensa, camuflaje, alimentación y comunicación.', '{"paragraph":4,"quote":"a widespread form of communication, concealment, and predation"}'::jsonb, '{"A":"Las herramientas registran la luz; no son su fuente principal.","B":"La reacción produce muy poco calor.","D":"Se mencionan animales pequeños y diversas especies, no solo peces depredadores."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000012'::uuid, '60000000-0000-4000-8000-000000000003'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Why can bioluminescence occur in delicate tissues?', '[{"id":"A","text":"The tissues are exposed to strong sunlight."},{"id":"B","text":"Ocean pressure prevents all chemical change."},{"id":"C","text":"The organisms produce light only after surfacing."},{"id":"D","text":"The reaction releases very little heat."}]'::jsonb, 'D', 'El primer párrafo vincula explícitamente la baja producción de calor con la ausencia de daño en tejidos delicados.', '{"paragraph":1,"quote":"this reaction produces very little heat"}'::jsonb, '{"A":"En el océano profundo la luz solar se desvanece.","B":"La presión no impide la reacción química.","C":"La bioluminiscencia sucede en el hábitat profundo, no solo en superficie."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000013'::uuid, '60000000-0000-4000-8000-000000000003'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 3, 2, 'Why does the author describe light-producing organs on the underside of an animal?', '[{"id":"A","text":"To illustrate how bioluminescence can provide camouflage"},{"id":"B","text":"To show that all deep-sea animals swim upside down"},{"id":"C","text":"To explain how sunlight damages internal organs"},{"id":"D","text":"To identify the hottest part of an animal’s body"}]'::jsonb, 'A', 'La luz inferior imita la iluminación que llega desde arriba y borra la silueta vista desde abajo.', '{"paragraph":2,"quote":"makes the animal’s silhouette harder to detect"}'::jsonb, '{"B":"La ubicación inferior no implica que el animal nade invertido.","C":"La función descrita es ocultar, no evitar daño solar.","D":"La reacción genera poco calor y no se localiza una región caliente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000014'::uuid, '60000000-0000-4000-8000-000000000003'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'The passage suggests that an animal flashing near a predator may benefit even if the flash does not frighten the predator because', '[{"id":"A","text":"the flash permanently removes the predator’s vision"},{"id":"B","text":"the flash may draw a larger attacker to the scene"},{"id":"C","text":"the animal can use the light as food"},{"id":"D","text":"sunlight will immediately return to the deep water"}]'::jsonb, 'B', 'El texto ofrece dos mecanismos defensivos: sobresaltar o atraer a un animal mayor que ataque al depredador inicial.', '{"paragraph":2,"quote":"attract a larger animal that then attacks the original predator"}'::jsonb, '{"A":"No se afirma que la pérdida de visión sea permanente.","C":"La luz atrae alimento en otros casos, pero no se consume como alimento.","D":"La presencia de luz solar no depende del destello."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000015'::uuid, '60000000-0000-4000-8000-000000000003'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 5, 2, 'The phrase “Such specimens” in paragraph 4 refers to', '[{"id":"A","text":"modern low-light cameras"},{"id":"B","text":"quiet remotely operated vehicles"},{"id":"C","text":"deep-sea animals brought to the surface"},{"id":"D","text":"chemical reactions inside tissues"}]'::jsonb, 'C', 'El grupo nominal retoma directamente a los animales que los científicos llevaban a la superficie para estudiarlos.', '{"paragraph":4,"quote":"animals brought to the surface. Such specimens"}'::jsonb, '{"A":"Las cámaras aparecen después como una mejora metodológica.","B":"Los vehículos son herramientas modernas, no especímenes.","D":"Las reacciones se estudian, pero no son organismos lesionados."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000016'::uuid, '60000000-0000-4000-8000-000000000004'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 1, 2, 'Which sentence best expresses the meaning of the final sentence?', '[{"id":"A","text":"Every eruption immediately creates soil suitable for farming."},{"id":"B","text":"The age of volcanic ash is the only factor that determines fertility."},{"id":"C","text":"Living organisms prevent minerals from entering volcanic soil."},{"id":"D","text":"Volcanic fertility develops gradually through geological, climatic, and biological processes."}]'::jsonb, 'D', 'La conclusión rechaza la idea de fertilidad inmediata y la atribuye a una interacción prolongada de varios factores.', '{"paragraph":4,"quote":"the result of a long interaction among rock, climate, and living organisms"}'::jsonb, '{"A":"El texto dice explícitamente que no es un regalo inmediato.","B":"La edad no basta; también intervienen clima, composición y pendiente.","C":"Los organismos aportan y estabilizan materia, no bloquean los minerales."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000017'::uuid, '60000000-0000-4000-8000-000000000004'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 2, 2, 'According to paragraph 2, all of the following contribute to early soil development EXCEPT', '[{"id":"A","text":"large amounts of organic matter already present in fresh ash"},{"id":"B","text":"nutrients released by weathering"},{"id":"C","text":"lichens growing on exposed particles"},{"id":"D","text":"plants trapping dust carried by wind"}]'::jsonb, 'A', 'La ceniza fresca casi no contiene materia orgánica; esta se acumula después mediante organismos pioneros y descomposición.', '{"paragraph":1,"quote":"contains almost no organic matter"}'::jsonb, '{"B":"La meteorización libera nutrientes según el segundo párrafo.","C":"Los líquenes estabilizan directamente la superficie expuesta.","D":"Las plantas resistentes atrapan polvo transportado por el viento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000018'::uuid, '60000000-0000-4000-8000-000000000004'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “hardy” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"brightly colored"},{"id":"B","text":"able to survive difficult conditions"},{"id":"C","text":"recently discovered"},{"id":"D","text":"dependent on deep soil"}]'::jsonb, 'B', 'Las plantas pioneras crecen sobre una superficie inestable y pobre, por lo que «hardy» significa resistentes.', '{"paragraph":2,"quote":"grasses and other hardy plants trap windblown dust"}'::jsonb, '{"A":"El color no participa en la función descrita.","C":"No se habla de cuándo fueron descubiertas.","D":"Estas plantas aparecen antes de que exista suelo profundo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000019'::uuid, '60000000-0000-4000-8000-000000000004'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 4, 2, 'What makes weathered volcanic soil capable of retaining water?', '[{"id":"A","text":"Repeated removal of protective vegetation"},{"id":"B","text":"The complete absence of decomposers"},{"id":"C","text":"Spaces created when mineral particles bind with organic material"},{"id":"D","text":"Large pieces of volcanic glass remaining unchanged"}]'::jsonb, 'C', 'El tercer párrafo explica que la unión de partículas finas y material descompuesto genera espacios que retienen agua y nutrientes.', '{"paragraph":3,"quote":"create spaces that retain both water and nutrients"}'::jsonb, '{"A":"Retirar la vegetación aumenta la erosión.","B":"Los descomponedores son necesarios para producir materia orgánica.","D":"La meteorización rompe el vidrio en partículas más finas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000020'::uuid, '60000000-0000-4000-8000-000000000004'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 1, 5, 3, 'What is the relationship between paragraphs 1–3 and paragraph 4?', '[{"id":"A","text":"The first three reject farming, and the fourth recommends a single crop."},{"id":"B","text":"The first three discuss dry climates, and the fourth discusses only humid ones."},{"id":"C","text":"The first three present a failed theory that the fourth replaces completely."},{"id":"D","text":"The first three describe a general process, and the fourth explains why its outcome varies."}]'::jsonb, 'D', 'Después de explicar la formación y fertilidad, el último párrafo introduce variables que hacen que cada depósito evolucione de forma distinta.', '{"paragraph":4,"quote":"Not every volcanic deposit follows the same path."}'::jsonb, '{"A":"El texto advierte sobre el manejo, pero no rechaza la agricultura ni propone cultivos.","B":"Los primeros párrafos no se limitan a climas secos.","C":"El último párrafo matiza el proceso, no lo descarta."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000021'::uuid, '60000000-0000-4000-8000-000000000005'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 1, 2, 'Why are seeds dried before they are placed in cold storage?', '[{"id":"A","text":"To slow their metabolism"},{"id":"B","text":"To make them germinate immediately"},{"id":"C","text":"To remove their genetic diversity"},{"id":"D","text":"To allow tropical insects to enter them"}]'::jsonb, 'A', 'El primer párrafo da la finalidad directa del secado: reducir la actividad metabólica durante el almacenamiento.', '{"paragraph":1,"quote":"workers dry the seeds to slow their metabolism"}'::jsonb, '{"B":"La germinación se prueba después; no debe comenzar al guardar.","C":"El banco intenta conservar la diversidad, no eliminarla.","D":"Los recipientes protegen las semillas y no buscan introducir insectos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000022'::uuid, '60000000-0000-4000-8000-000000000005'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 2, 2, 'Why might a bank grow plants from many stored seeds during regeneration?', '[{"id":"A","text":"To ensure that all plants become genetically identical"},{"id":"B","text":"To preserve as much of the original genetic variation as possible"},{"id":"C","text":"To avoid collecting any new seeds"},{"id":"D","text":"To make the storage rooms warmer"}]'::jsonb, 'B', 'El riesgo de reproducir pocas plantas es perder diversidad; usar muchas reduce ese efecto de muestreo.', '{"paragraph":2,"quote":"if only a few plants reproduce, some of the original genetic diversity may be lost"}'::jsonb, '{"A":"La identidad genética reduciría precisamente la diversidad.","C":"La regeneración tiene como objetivo producir semillas frescas.","D":"La temperatura de la cámara no depende de cuántas plantas se cultiven."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000023'::uuid, '60000000-0000-4000-8000-000000000005'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “passive” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"located outdoors"},{"id":"B","text":"unable to remain cold"},{"id":"C","text":"requiring no active attention"},{"id":"D","text":"limited to one species"}]'::jsonb, 'C', 'La oración siguiente enumera pruebas y regeneración periódicas, mostrando que guardar semillas exige intervención continua.', '{"paragraph":2,"quote":"Storage is not completely passive."}'::jsonb, '{"A":"La ubicación del almacenamiento no define «passive».","B":"El frío es una condición controlada, no una incapacidad.","D":"El banco conserva múltiples variedades y especies."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000024'::uuid, '60000000-0000-4000-8000-000000000005'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 4, 2, 'Which type of plant is NOT well suited to ordinary seed-bank storage?', '[{"id":"A","text":"A species whose dry seeds survive for decades"},{"id":"B","text":"A crop variety that has disappeared from farms"},{"id":"C","text":"A plant whose seeds can germinate after cold storage"},{"id":"D","text":"A species whose seeds are harmed by drying"}]'::jsonb, 'D', 'El tercer párrafo identifica como excepción las semillas tropicales dañadas por secado o congelación.', '{"paragraph":3,"quote":"seeds that are damaged by drying or freezing"}'::jsonb, '{"A":"La supervivencia prolongada es justamente una condición favorable.","B":"Conservar variedades desaparecidas de granjas es una función del banco.","C":"La germinación posterior demuestra viabilidad en almacenamiento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000025'::uuid, '60000000-0000-4000-8000-000000000005'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 5, 2, 'Which statement best summarizes the passage?', '[{"id":"A","text":"Seed banks preserve many plants through active management but must be combined with other methods."},{"id":"B","text":"Seed banks can replace the protection of every natural ecosystem."},{"id":"C","text":"Freezing works equally well for the seeds of all plants."},{"id":"D","text":"Once stored, seeds never need to be tested or renewed."}]'::jsonb, 'A', 'El texto combina el funcionamiento y mantenimiento de los bancos con sus límites y la necesidad de estrategias complementarias.', '{"paragraph":3,"quote":"one part of a broader strategy rather than a complete replacement"}'::jsonb, '{"B":"La conclusión niega que sean un reemplazo completo.","C":"Algunas semillas resultan dañadas por congelación.","D":"Las muestras se prueban y regeneran periódicamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000026'::uuid, '60000000-0000-4000-8000-000000000006'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 3, 'What is the author’s primary purpose?', '[{"id":"A","text":"To prove that landmarks are useless during all migrations"},{"id":"B","text":"To explain evidence that birds use Earth’s magnetic field for both direction and location"},{"id":"C","text":"To describe how humans should build magnetic compasses"},{"id":"D","text":"To argue that one sensory mechanism has been conclusively identified"}]'::jsonb, 'B', 'El pasaje distingue brújula y mapa magnéticos, describe experimentos y reconoce que el mecanismo sensorial sigue abierto.', '{"paragraph":3,"quote":"This response suggests that they interpreted the artificial field as location information."}'::jsonb, '{"A":"Los puntos de referencia son una de varias señales útiles.","C":"La comparación con una brújula humana es explicativa, no una instrucción de construcción.","D":"El último párrafo afirma que el mecanismo continúa debatido."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000027'::uuid, '60000000-0000-4000-8000-000000000006'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'Which property of Earth’s magnetic field varies from place to place?', '[{"id":"A","text":"The number of coastlines it crosses"},{"id":"B","text":"The visibility of the stars"},{"id":"C","text":"Its strength"},{"id":"D","text":"The age of nearby birds"}]'::jsonb, 'C', 'El segundo párrafo menciona dos variaciones geográficas: el ángulo de las líneas y la intensidad del campo.', '{"paragraph":2,"quote":"its strength changes from place to place"}'::jsonb, '{"A":"Las costas son puntos de referencia visuales, no propiedades del campo.","B":"La visibilidad estelar depende de nubes y luz.","D":"La edad de las aves no forma parte del campo magnético."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000028'::uuid, '60000000-0000-4000-8000-000000000006'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 3, 2, 'Which statement best expresses the distinction made in paragraph 2?', '[{"id":"A","text":"A compass can identify every landmark, but a map cannot."},{"id":"B","text":"Magnetic strength is identical everywhere, whereas direction changes."},{"id":"C","text":"A map is useful only to birds that have never migrated."},{"id":"D","text":"Direction alone tells a bird where to head, while a map-like signal can also indicate where it currently is."}]'::jsonb, 'D', 'El párrafo diferencia información direccional de información posicional; detectar ambas permitiría decidir la ruta desde un lugar concreto.', '{"paragraph":2,"quote":"A compass indicates direction"}'::jsonb, '{"A":"Los puntos de referencia no son identificados por una brújula.","B":"El texto señala que la intensidad sí cambia geográficamente.","C":"No se limita el uso de un mapa a aves sin experiencia."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000029'::uuid, '60000000-0000-4000-8000-000000000006'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 3, 'Why does the author mention coils surrounding an enclosure?', '[{"id":"A","text":"To explain how researchers alter magnetic information without moving the birds"},{"id":"B","text":"To show how birds are trained to recognize mountains"},{"id":"C","text":"To provide evidence that birds cannot fly inside laboratories"},{"id":"D","text":"To describe a device that blocks every sensory cue"}]'::jsonb, 'A', 'Las bobinas reproducen condiciones magnéticas de otro sitio mientras el ave permanece físicamente en el mismo lugar.', '{"paragraph":3,"quote":"reproduce the magnetic conditions of another region"}'::jsonb, '{"B":"El procedimiento no enseña montañas ni otros rasgos visuales.","C":"La dirección intentada por las aves es la variable observada, no su incapacidad de volar.","D":"Se modifica la señal magnética; no se afirma que se eliminen todas las demás."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000030'::uuid, '60000000-0000-4000-8000-000000000006'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 3, 'How would the author’s attitude toward explanations of magnetic sensing best be described?', '[{"id":"A","text":"Certain that magnetic particles explain every species"},{"id":"B","text":"Cautious and open to multiple mechanisms"},{"id":"C","text":"Dismissive of experimental evidence"},{"id":"D","text":"Concerned that migration should be stopped"}]'::jsonb, 'B', 'El autor presenta hipótesis, señala incertidumbre y permite que mecanismos diferentes funcionen juntos o varíen entre especies.', '{"paragraph":4,"quote":"These explanations are not necessarily exclusive"}'::jsonb, '{"A":"El papel exacto de las partículas se considera incierto.","C":"Los experimentos se usan como evidencia a favor de información posicional.","D":"No existe ninguna propuesta de detener la migración."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000031'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Which topic is developed throughout the passage?', '[{"id":"A","text":"Why coral colonies migrate between reefs each year"},{"id":"B","text":"How predators determine the phases of the moon"},{"id":"C","text":"How multiple environmental signals coordinate coral spawning and why that timing matters"},{"id":"D","text":"Why all coral species spawn at exactly the same moment"}]'::jsonb, 'C', 'El texto explica las señales temporales, ventajas, variaciones, amenazas climáticas y utilidad científica del desove sincronizado.', '{"paragraph":6,"quote":"Understanding the reef’s multiple clocks helps teams prepare"}'::jsonb, '{"A":"Las colonias permanecen fijas; son las larvas las que se dispersan.","B":"La luna ayuda a sincronizar, pero los depredadores no determinan su ciclo.","D":"Las especies pueden desovar en noches u horas distintas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000032'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'Which signal helps narrow spawning to a particular hour?', '[{"id":"A","text":"The age of the reef’s hard surface"},{"id":"B","text":"The number of predators present"},{"id":"C","text":"The distance traveled by larvae"},{"id":"D","text":"The change from daylight to darkness"}]'::jsonb, 'D', 'El segundo párrafo asigna escalas: temperatura para el mes, luna para noches y transición a oscuridad para la hora.', '{"paragraph":2,"quote":"the transition from daylight to darkness helps coordinate the hour"}'::jsonb, '{"A":"La superficie importa para el asentamiento posterior.","B":"La abundancia de depredadores no aparece como reloj.","C":"El viaje larvario ocurre después de la fecundación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000033'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “rigid” in paragraph 4 is closest in meaning to', '[{"id":"A","text":"unable to vary"},{"id":"B","text":"easy to observe"},{"id":"C","text":"limited to deep water"},{"id":"D","text":"controlled by predators"}]'::jsonb, 'A', 'La oración contrasta precisión con cambios de una noche o más causados por condiciones locales.', '{"paragraph":4,"quote":"precise but not perfectly rigid"}'::jsonb, '{"B":"La facilidad de observación no es el contraste presentado.","C":"No se restringe el fenómeno a aguas profundas.","D":"Los depredadores afectan supervivencia, no la flexibilidad del calendario."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000034'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why can synchronized release improve fertilization for stationary colonies?', '[{"id":"A","text":"It allows adult colonies to swim toward one another."},{"id":"B","text":"It places reproductive cells from many colonies in the water together."},{"id":"C","text":"It prevents currents from moving any reproductive cells."},{"id":"D","text":"It guarantees that every released egg survives."}]'::jsonb, 'B', 'Las colonias no pueden buscar pareja; liberar células simultáneamente aumenta la probabilidad de encuentro entre colonias.', '{"paragraph":1,"quote":"increases the chance that reproductive cells from different colonies will meet"}'::jsonb, '{"A":"Los adultos no se desplazan.","C":"Las corrientes transportan huevos fecundados.","D":"La sincronía mejora probabilidades, pero no garantiza supervivencia total."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000035'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 5, 3, 'The phrase “This effect” in paragraph 3 refers to', '[{"id":"A","text":"larvae settling on hard surfaces"},{"id":"B","text":"corals responding to moonlight"},{"id":"C","text":"predators being unable to consume all the reproductive bundles"},{"id":"D","text":"researchers collecting bundles"}]'::jsonb, 'C', 'El demostrativo retoma la saturación producida cuando aparecen demasiados paquetes para que los depredadores los consuman todos.', '{"paragraph":3,"quote":"predators cannot consume all of them. This effect"}'::jsonb, '{"A":"El asentamiento se explica después.","B":"La respuesta lunar pertenece al párrafo anterior.","D":"La recolección científica aparece al final del pasaje."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000036'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 2, 'All of the following are mentioned as factors that can shift or disrupt spawning EXCEPT', '[{"id":"A","text":"heavy rainfall near shore"},{"id":"B","text":"unusual water temperatures"},{"id":"C","text":"severe bleaching stress"},{"id":"D","text":"the hardness of the surface beneath an adult colony"}]'::jsonb, 'D', 'La dureza de la superficie se relaciona con el asentamiento de larvas, no con el momento de desove de colonias adultas.', '{"paragraph":3,"quote":"suitable hard surfaces"}'::jsonb, '{"A":"La lluvia intensa puede reducir la salinidad y desplazar el evento.","B":"Temperaturas inusuales alteran el desarrollo.","C":"El estrés por blanqueamiento puede reducir o impedir el desove."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000037'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 2, 7, 2, 'Why does the author describe predator satiation?', '[{"id":"A","text":"To identify a survival advantage of releasing many bundles simultaneously"},{"id":"B","text":"To explain why corals produce no larvae"},{"id":"C","text":"To show that fish coordinate spawning dates"},{"id":"D","text":"To argue that predators should be removed from reefs"}]'::jsonb, 'A', 'La saturación de depredadores explica por qué una liberación masiva permite que al menos una proporción escape y sobreviva.', '{"paragraph":3,"quote":"allows a proportion to survive"}'::jsonb, '{"B":"El proceso conduce a larvas tras la fecundación.","C":"Los peces responden al evento, pero no fijan su fecha.","D":"No se propone eliminar depredadores del ecosistema."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000038'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 8, 3, 'Which statement best expresses the idea that climate change may cause signals to become “less closely aligned”?', '[{"id":"A","text":"All environmental signals will permanently disappear."},{"id":"B","text":"Temperature cues may shift while lunar and daylight cues retain a different schedule."},{"id":"C","text":"Corals will begin using predators as their only clock."},{"id":"D","text":"Moon phases will change in response to warmer oceans."}]'::jsonb, 'B', 'El calentamiento puede modificar los patrones térmicos sin modificar de la misma manera los ciclos lunar y diario.', '{"paragraph":5,"quote":"warming changes temperature patterns differently from lunar and daylight cycles"}'::jsonb, '{"A":"El texto habla de desajuste, no de desaparición total.","C":"Los depredadores no se presentan como señal temporal.","D":"El calentamiento no altera las fases lunares según el pasaje."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000039'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'The author’s discussion of scientific prediction is best described as', '[{"id":"A","text":"dismissive, claiming that records have no value"},{"id":"B","text":"certain, stating that calendars always predict the exact night"},{"id":"C","text":"measured, emphasizing both useful patterns and local uncertainty"},{"id":"D","text":"alarmist, arguing that restoration work is impossible"}]'::jsonb, 'C', 'Se reconoce que los registros y señales ayudan, pero se insiste en medir condiciones y observar colonias locales.', '{"paragraph":4,"quote":"combine long-term records with current measurements rather than relying on a calendar date alone"}'::jsonb, '{"A":"Los registros se combinan con datos actuales; no se descartan.","B":"El evento puede desplazarse una noche o más.","D":"La restauración es exigente, no imposible."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000040'::uuid, '60000000-0000-4000-8000-000000000007'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 2, 'How does the final paragraph contribute to the passage?', '[{"id":"A","text":"It introduces the first evidence that corals are living animals."},{"id":"B","text":"It replaces environmental signals with a fixed calendar."},{"id":"C","text":"It explains why larvae can never be raised under controlled conditions."},{"id":"D","text":"It connects knowledge of spawning timing to coral restoration work."}]'::jsonb, 'D', 'El cierre pasa de la explicación biológica a una aplicación práctica: recolectar y criar corales para restauración.', '{"paragraph":6,"quote":"raise young corals for restoration projects"}'::jsonb, '{"A":"La naturaleza viva de los pólipos se presenta al comienzo.","B":"El párrafo reafirma la necesidad de observación local, no de una fecha fija.","C":"Se describe explícitamente la cría controlada como posible."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000041'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Which statement best captures the central focus of the passage?', '[{"id":"A","text":"The processes that move organic carbon from surface waters into the deep ocean"},{"id":"B","text":"The use of artificial snow to cool the ocean surface"},{"id":"C","text":"The reasons photosynthesis occurs only on the seafloor"},{"id":"D","text":"A single instrument that measures all ocean carbon exactly"}]'::jsonb, 'A', 'El pasaje sigue la formación, descenso, transformación, transporte animal, almacenamiento y medición del carbono oceánico.', '{"paragraph":7,"quote":"understanding its descent is central to explaining how the ocean regulates atmospheric carbon"}'::jsonb, '{"B":"La nieve marina es material orgánico natural, no nieve artificial.","C":"La fotosíntesis ocurre en la zona iluminada superior.","D":"El cierre destaca que cada método captura solo una parte."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000042'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'What causes small particles to descend more rapidly?', '[{"id":"A","text":"Their complete conversion into dissolved carbon"},{"id":"B","text":"Their collision and combination into larger aggregates"},{"id":"C","text":"Their movement into warmer surface water"},{"id":"D","text":"Their exposure to brighter underwater lights"}]'::jsonb, 'B', 'El segundo párrafo señala que las partículas que chocan y se adhieren forman agregados mayores con mayor velocidad de hundimiento.', '{"paragraph":2,"quote":"forming larger aggregates that descend more rapidly"}'::jsonb, '{"A":"El carbono disuelto ya no desciende como partícula.","C":"El agua cálida acelera microbios, no necesariamente el hundimiento.","D":"Las luces permiten observar, pero no impulsan las partículas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000043'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “shield” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"measure"},{"id":"B","text":"dissolve"},{"id":"C","text":"protect"},{"id":"D","text":"heat"}]'::jsonb, 'C', 'Los minerales pueden cubrir o asociarse con materia orgánica y reducir su exposición a las bacterias.', '{"paragraph":3,"quote":"shield some organic material from bacteria"}'::jsonb, '{"A":"Medir corresponde a las herramientas científicas del final.","B":"La protección reduce la descomposición, no la disolución.","D":"El calentamiento se discute como factor climático distinto."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000044'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 2, 'Why does the author mention zooplankton waste pellets?', '[{"id":"A","text":"To show that zooplankton perform photosynthesis"},{"id":"B","text":"To explain why all particles remain near the surface"},{"id":"C","text":"To identify the only source of carbon in seawater"},{"id":"D","text":"To give another mechanism that concentrates material into faster-sinking particles"}]'::jsonb, 'D', 'Junto con la agregación por colisiones, los pellets densos empaquetan material fino y aceleran su descenso.', '{"paragraph":2,"quote":"Zooplankton also package fine material into dense waste pellets."}'::jsonb, '{"A":"Los productores fotosintéticos mencionados son algas.","B":"El empaquetamiento acorta el tiempo cerca de la superficie.","C":"El carbono también procede de células muertas y otros materiales."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000045'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 3, 'Which sentence best expresses the idea in paragraph 4?', '[{"id":"A","text":"Daily animal migrations transport carbon downward even when particles do not simply sink."},{"id":"B","text":"Animals prevent every form of carbon from reaching deep water."},{"id":"C","text":"Predators carry carbon upward only during daylight."},{"id":"D","text":"Passive sinking and animal movement are exactly the same process."}]'::jsonb, 'A', 'Los animales ingieren carbono arriba y lo liberan abajo; es transporte activo distinto del hundimiento, pero con dirección general similar.', '{"paragraph":4,"quote":"This active transport differs from passive sinking"}'::jsonb, '{"B":"El transporte animal contribuye al movimiento hacia profundidad.","C":"Las especies bajan de día para evitar depredadores, no son estos quienes llevan carbono arriba.","D":"El texto diferencia explícitamente ambos mecanismos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000046'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 2, 6, 3, 'Why is carbon reaching greater depths generally isolated from the atmosphere for longer?', '[{"id":"A","text":"Deep water contains no carbon-consuming organisms."},{"id":"B","text":"It takes ocean circulation more time to return it to surface waters."},{"id":"C","text":"The atmosphere stops exchanging gases at night."},{"id":"D","text":"All deep carbon immediately becomes seafloor rock."}]'::jsonb, 'B', 'El tiempo de almacenamiento aumenta con profundidad y ubicación porque el retorno mediante circulación puede tomar décadas o siglos.', '{"paragraph":5,"quote":"Ocean circulation can eventually bring it back toward the surface"}'::jsonb, '{"A":"El texto describe consumo bacteriano durante el descenso.","C":"El intercambio atmosférico no se limita por horario nocturno.","D":"Solo una fracción mucho menor queda enterrada en sedimentos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000047'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 7, 2, 'All of the following are mentioned as affecting how far particles carry carbon EXCEPT', '[{"id":"A","text":"microbial activity"},{"id":"B","text":"particle composition"},{"id":"C","text":"the brightness of the moon"},{"id":"D","text":"the presence of minerals"}]'::jsonb, 'C', 'La luz lunar no aparece como factor del hundimiento; sí se describen temperatura microbiana, composición y minerales.', '{"paragraph":3,"quote":"The amount that reaches deep water varies widely."}'::jsonb, '{"A":"Los microbios consumen materia mientras cae.","B":"La facilidad de descomposición depende de la composición.","D":"Los minerales añaden peso y pueden proteger materia orgánica."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000048'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 8, 3, 'The phrase “These interacting effects” in paragraph 6 refers to', '[{"id":"A","text":"the use of lights and sediment traps"},{"id":"B","text":"the burial of all carbon on the seafloor"},{"id":"C","text":"the daily schedule of migrating predators"},{"id":"D","text":"changes in nutrient supply and plankton-related particle properties"}]'::jsonb, 'D', 'La frase resume la estratificación, disponibilidad de nutrientes y cambios en especies, tamaño, minerales y consumo.', '{"paragraph":6,"quote":"These interacting effects make a single global prediction difficult."}'::jsonb, '{"A":"Las herramientas de medición se presentan en el párrafo siguiente.","B":"Solo una pequeña cantidad llega a enterrarse.","C":"La migración animal se explica antes, pero no es el conjunto inmediato retomado."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000049'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'What is the author’s attitude toward predicting future changes in the biological carbon pump?', '[{"id":"A","text":"Cautious because several mechanisms may change in different directions"},{"id":"B","text":"Completely confident that warming will strengthen it everywhere"},{"id":"C","text":"Uninterested because the process has no atmospheric effect"},{"id":"D","text":"Certain that one camera can resolve every uncertainty"}]'::jsonb, 'A', 'El autor presenta efectos contrapuestos y concluye que una predicción global única resulta difícil.', '{"paragraph":6,"quote":"make a single global prediction difficult"}'::jsonb, '{"B":"La producción puede reducirse en algunas regiones y no se ofrece una conclusión universal.","C":"El proceso se vincula directamente con carbono atmosférico.","D":"Las cámaras no miden carbono directamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000050'::uuid, '60000000-0000-4000-8000-000000000008'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'Why does the passage end by comparing several research methods?', '[{"id":"A","text":"To demonstrate that sediment traps never affect currents"},{"id":"B","text":"To show why estimates are strongest when independent approaches agree"},{"id":"C","text":"To argue that direct observation makes models unnecessary"},{"id":"D","text":"To change the subject from carbon to instrument sales"}]'::jsonb, 'B', 'El último párrafo reconoce límites de cada técnica y justifica combinar evidencia independiente.', '{"paragraph":7,"quote":"Agreement among independent methods therefore provides stronger evidence"}'::jsonb, '{"A":"Las trampas pueden alterar corrientes.","C":"Los modelos siguen siendo una de las herramientas combinadas.","D":"La comparación metodológica apoya el estudio del mismo proceso de carbono."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000051'::uuid, '60000000-0000-4000-8000-000000000009'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 1, 'Which description best captures the modern public library?', '[{"id":"A","text":"Public libraries have stopped lending books entirely."},{"id":"B","text":"Digital services have made public buildings unnecessary."},{"id":"C","text":"Public libraries preserve access to knowledge while expanding their services and spaces."},{"id":"D","text":"Libraries now require every visitor to buy something."}]'::jsonb, 'C', 'El texto presenta una ampliación de funciones y concluye que la biblioteca combina continuidad con adaptación.', '{"paragraph":3,"quote":"balances continuity with adaptation"}'::jsonb, '{"A":"Los libros siguen formando parte de la misión.","B":"La falta de acceso doméstico vuelve importantes los espacios físicos.","D":"Permanecer sin comprar se presenta como una característica distintiva."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000052'::uuid, '60000000-0000-4000-8000-000000000009'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'Why are library computers described as infrastructure for some residents?', '[{"id":"A","text":"They preserve every local record automatically."},{"id":"B","text":"They eliminate the need for staff assistance."},{"id":"C","text":"They are used only for entertainment."},{"id":"D","text":"They may be the residents’ only reliable way to access online services."}]'::jsonb, 'D', 'El primer párrafo vincula esos equipos con personas que no tienen dispositivos o conexión confiable en casa.', '{"paragraph":1,"quote":"lack reliable devices or connections at home"}'::jsonb, '{"A":"La preservación de registros requiere trabajo especializado.","B":"El texto menciona asistencia con formularios digitales.","C":"Se destacan solicitudes, estudio y servicios, no solo entretenimiento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000053'::uuid, '60000000-0000-4000-8000-000000000009'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 3, 1, 'Why does the author mention a student, a job seeker, and a recently arrived resident?', '[{"id":"A","text":"To illustrate different uses of the same accessible public space"},{"id":"B","text":"To rank visitors according to their reading ability"},{"id":"C","text":"To show that only three groups may enter libraries"},{"id":"D","text":"To argue that language classes should replace books"}]'::jsonb, 'A', 'Los tres ejemplos concretan actividades distintas que comparten un espacio abierto y sin obligación de compra.', '{"paragraph":2,"quote":"These activities differ, yet they share the same accessible setting."}'::jsonb, '{"B":"No se comparan niveles de lectura.","C":"Los ejemplos no constituyen una lista exclusiva.","D":"Las clases complementan, no sustituyen, el acceso al conocimiento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000054'::uuid, '60000000-0000-4000-8000-000000000009'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 4, 1, 'The word “accommodate” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"prevent"},{"id":"B","text":"make room for"},{"id":"C","text":"measure"},{"id":"D","text":"record permanently"}]'::jsonb, 'B', 'El edificio debe permitir conversaciones y talleres al mismo tiempo que conserva zonas silenciosas.', '{"paragraph":3,"quote":"must accommodate conversation, workshops, and group work"}'::jsonb, '{"A":"La biblioteca intenta permitir esas actividades, no impedirlas.","C":"No se trata de calcular su tamaño.","D":"Registrar información no expresa adaptar el espacio."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000055'::uuid, '60000000-0000-4000-8000-000000000009'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 2, 'What can be inferred about the skills required of modern library staff?', '[{"id":"A","text":"They are limited to arranging printed books."},{"id":"B","text":"They no longer include preservation work."},{"id":"C","text":"They have become more varied as library services have expanded."},{"id":"D","text":"They are identical in every library building."}]'::jsonb, 'C', 'El texto enumera desde preservación hasta privacidad digital, lo que implica un campo de competencias más amplio.', '{"paragraph":3,"quote":"skills that range from preserving local records to teaching digital privacy"}'::jsonb, '{"A":"La organización de libros no cubre la variedad descrita.","B":"La preservación se menciona explícitamente.","D":"Las necesidades pueden variar según servicios y comunidad."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000056'::uuid, '60000000-0000-4000-8000-000000000010'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 1, 'What does the author seek to explain about temporary markets?', '[{"id":"A","text":"To provide instructions for building a permanent shopping center"},{"id":"B","text":"To show that street markets leave no lasting effects"},{"id":"C","text":"To argue that residents should control all vendor prices"},{"id":"D","text":"To explain the opportunities and negotiations created by temporary street markets"}]'::jsonb, 'D', 'El pasaje combina efectos económicos, barreras de entrada, tensiones y acuerdos sobre el uso del espacio.', '{"paragraph":3,"quote":"a recurring agreement about how public space will be shared"}'::jsonb, '{"A":"El objeto de estudio es un mercado temporal.","B":"Las conexiones pueden continuar después de desmontar los puestos.","C":"La fijación de precios no se atribuye a residentes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000057'::uuid, '60000000-0000-4000-8000-000000000010'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'How can a weekly stall help a small producer?', '[{"id":"A","text":"It allows the producer to test demand with less financial risk."},{"id":"B","text":"It guarantees a permanent location."},{"id":"C","text":"It prevents customers from visiting nearby shops."},{"id":"D","text":"It removes the need to follow local rules."}]'::jsonb, 'A', 'El segundo párrafo contrasta el costo de una tienda permanente con la posibilidad de probar productos en un puesto.', '{"paragraph":2,"quote":"a weekly stall can be tested with less risk"}'::jsonb, '{"B":"La ubicación es temporal y puede ser objeto de negociación.","C":"Los comercios cercanos incluso pueden recibir más tránsito.","D":"Los vendedores necesitan reglas predecibles, no ausencia de reglas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000058'::uuid, '60000000-0000-4000-8000-000000000010'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 3, 1, 'The phrase “The flexibility” in paragraph 3 refers to', '[{"id":"A","text":"the length of permanent store contracts"},{"id":"B","text":"the temporary and adjustable nature of the market"},{"id":"C","text":"the fixed prices of nearby businesses"},{"id":"D","text":"the construction of new parking areas"}]'::jsonb, 'B', 'La frase retoma la facilidad para instalar, probar y modificar un puesto sin una tienda permanente.', '{"paragraph":3,"quote":"The flexibility also creates tension."}'::jsonb, '{"A":"Los contratos largos representan la alternativa menos flexible.","C":"No se discuten precios fijos.","D":"El estacionamiento aparece como posible conflicto, no como nueva construcción."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000059'::uuid, '60000000-0000-4000-8000-000000000010'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 4, 1, 'According to the passage, residents may object to all of the following EXCEPT', '[{"id":"A","text":"noise"},{"id":"B","text":"blocked parking"},{"id":"C","text":"vendors observing which products buyers prefer"},{"id":"D","text":"waste"}]'::jsonb, 'C', 'La observación de demanda se presenta como ventaja empresarial, no como una queja vecinal.', '{"paragraph":2,"quote":"Vendors can observe which products attract buyers"}'::jsonb, '{"A":"El ruido figura entre las objeciones.","B":"El bloqueo de estacionamiento se menciona como tensión.","D":"Los residuos también aparecen en la lista de preocupaciones."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000060'::uuid, '60000000-0000-4000-8000-000000000010'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 2, 'Which sentence best expresses the final idea of the passage?', '[{"id":"A","text":"A market succeeds only when its stalls become permanent."},{"id":"B","text":"Public space cannot support both residents and vendors."},{"id":"C","text":"Market organizers make decisions without consulting anyone else."},{"id":"D","text":"A recurring market depends on continuing cooperation over the use of shared space."}]'::jsonb, 'D', 'La conclusión redefine el mercado como un acuerdo repetido entre varios actores, no solo como estructuras físicas.', '{"paragraph":3,"quote":"a recurring agreement about how public space will be shared"}'::jsonb, '{"A":"La temporalidad es una característica central.","B":"El texto plantea negociación, no incompatibilidad absoluta.","C":"Gobierno, negocios y residentes participan junto con organizadores."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000061'::uuid, '60000000-0000-4000-8000-000000000011'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Which statement best summarizes the development described in the passage?', '[{"id":"A","text":"Faster transport and communication encouraged societies to replace local solar times with shared standards."},{"id":"B","text":"Town clocks became inaccurate because the sun changed speed."},{"id":"C","text":"Governments created railways mainly to eliminate public clocks."},{"id":"D","text":"Local time differences increased after standard zones were adopted."}]'::jsonb, 'A', 'El argumento conecta la coordinación creada por tren y telégrafo con la adopción gradual de horarios regionales.', '{"paragraph":4,"quote":"replacing many locally observed noons with a smaller number of socially agreed ones"}'::jsonb, '{"B":"La variación provenía de la posición solar local, no de un cambio en la velocidad del sol.","C":"Los ferrocarriles motivaron la estandarización, no fueron creados para retirar relojes.","D":"Las zonas redujeron la cantidad de horarios usados."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000062'::uuid, '60000000-0000-4000-8000-000000000011'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Why did local solar time create few problems before railroads?', '[{"id":"A","text":"All towns had clocks showing identical minutes."},{"id":"B","text":"Most coordination occurred among people in the same area."},{"id":"C","text":"Telegraph messages traveled very slowly."},{"id":"D","text":"People never traveled beyond their own towns."}]'::jsonb, 'B', 'Con transporte y comunicación lentos, las actividades se coordinaban principalmente dentro de un entorno local.', '{"paragraph":1,"quote":"coordinate activities only with others nearby"}'::jsonb, '{"A":"Los relojes de lugares distintos podían diferir.","C":"El telégrafo todavía no era la condición descrita y luego transmitía casi al instante.","D":"El texto habla de menor necesidad de coordinación distante, no de ausencia total de viajes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000063'::uuid, '60000000-0000-4000-8000-000000000011'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 3, 2, 'Why does the author give the example of a nine o’clock departure?', '[{"id":"A","text":"To show that all trains left in the morning"},{"id":"B","text":"To identify the first legally established time zone"},{"id":"C","text":"To illustrate the ambiguity created by multiple time systems"},{"id":"D","text":"To argue that printed schedules were unnecessary"}]'::jsonb, 'C', 'El ejemplo muestra que una misma hora impresa podía referirse a relojes diferentes.', '{"paragraph":2,"quote":"might refer to station time, railway headquarters time, or the time of another city"}'::jsonb, '{"A":"La hora es ilustrativa y no define todos los itinerarios.","B":"No se asocia con la primera zona legal.","D":"La dificultad era interpretar horarios, no prescindir de ellos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000064'::uuid, '60000000-0000-4000-8000-000000000011'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why might some municipal leaders have resisted railway time?', '[{"id":"A","text":"They wanted telegraph messages to travel more slowly."},{"id":"B","text":"They believed the sun no longer reached its highest point."},{"id":"C","text":"They preferred schedules that listed no departure times."},{"id":"D","text":"They believed accepting it could reduce a visible sign of local autonomy."}]'::jsonb, 'D', 'El texto afirma que el tiempo local podía simbolizar independencia; sustituirlo implicaba ceder una convención propia.', '{"paragraph":3,"quote":"local time as a symbol of independence"}'::jsonb, '{"A":"La velocidad del telégrafo no dependía de la preferencia municipal.","B":"El mediodía solar seguía existiendo.","C":"La resistencia era al estándar, no a toda información horaria."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000065'::uuid, '60000000-0000-4000-8000-000000000011'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 3, 'How does the author characterize modern time zones?', '[{"id":"A","text":"As useful social agreements whose apparent naturalness hides historical choices"},{"id":"B","text":"As exact representations of solar noon everywhere"},{"id":"C","text":"As failures that created more confusion than local time"},{"id":"D","text":"As systems determined only by geography"}]'::jsonb, 'A', 'La conclusión reconoce la utilidad de coordinación y a la vez subraya su carácter negociado, político y económico.', '{"paragraph":4,"quote":"negotiated systems rather than direct copies of solar time"}'::jsonb, '{"B":"Las fronteras se apartan del mediodía solar local.","C":"El texto afirma que resolvieron problemas genuinos.","D":"Las fronteras también siguen relaciones políticas y económicas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000066'::uuid, '60000000-0000-4000-8000-000000000012'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 2, 'What is the passage mainly intended to explain?', '[{"id":"A","text":"Why official maps should contain no roads"},{"id":"B","text":"How community mapping adds residents’ experience to technical information"},{"id":"C","text":"How phones automatically resolve social inequality"},{"id":"D","text":"Why residents always agree about public space"}]'::jsonb, 'B', 'El texto describe qué aporta la cartografía comunitaria, cómo se realiza y qué límites debe reconocer.', '{"paragraph":3,"quote":"place lived experience alongside them"}'::jsonb, '{"A":"Las carreteras son un ejemplo útil de información oficial.","C":"Los teléfonos son una herramienta, no una solución social automática.","D":"Las experiencias pueden diferir entre grupos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000067'::uuid, '60000000-0000-4000-8000-000000000012'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Which information might residents add to a land-use map?', '[{"id":"A","text":"The legal definition of every national border"},{"id":"B","text":"The time shown by railway headquarters"},{"id":"C","text":"An entrance that becomes blocked during seasonal flooding"},{"id":"D","text":"The chemical composition of volcanic ash"}]'::jsonb, 'C', 'El primer párrafo ofrece directamente la obstrucción estacional como información que un mapa de edificios podría omitir.', '{"paragraph":1,"quote":"where seasonal flooding blocks an entrance"}'::jsonb, '{"A":"Las fronteras nacionales no son el ejemplo local presentado.","B":"El tiempo ferroviario pertenece a otro problema.","D":"La composición mineral requeriría otro tipo de estudio."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000068'::uuid, '60000000-0000-4000-8000-000000000012'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 3, 2, 'Why can comparing observations improve a map?', '[{"id":"A","text":"It guarantees that every participant uses a wheelchair."},{"id":"B","text":"It removes the need to record participation."},{"id":"C","text":"It makes technical surveys permanently inaccurate."},{"id":"D","text":"It reveals needs that may be visible to one group but not another."}]'::jsonb, 'D', 'El contraste entre ruta iluminada y accesibilidad demuestra que usuarios distintos detectan características distintas.', '{"paragraph":2,"quote":"groups experience the same place differently"}'::jsonb, '{"A":"La silla de ruedas es un ejemplo de perspectiva, no una condición universal.","B":"Registrar quién participó sigue siendo necesario.","C":"El objetivo es complementar las encuestas técnicas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000069'::uuid, '60000000-0000-4000-8000-000000000012'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 4, 2, 'The word “neutral” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"free from the influence of particular perspectives"},{"id":"B","text":"drawn without color"},{"id":"C","text":"impossible to share"},{"id":"D","text":"limited to printed paper"}]'::jsonb, 'A', 'El párrafo advierte que quién participa influye en el conocimiento representado; «neutral» alude a ausencia de sesgo de perspectiva.', '{"paragraph":3,"quote":"not automatically complete or neutral"}'::jsonb, '{"B":"El uso de color no se discute.","C":"Los proyectos se basan precisamente en compartir observaciones.","D":"Se admiten mapas impresos, teléfonos y fotografías."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000070'::uuid, '60000000-0000-4000-8000-000000000012'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 5, 2, 'All of the following are mentioned as ways to contribute to a community map EXCEPT', '[{"id":"A","text":"drawing on a printed map"},{"id":"B","text":"changing a national law"},{"id":"C","text":"collecting phone coordinates"},{"id":"D","text":"annotating photographs"}]'::jsonb, 'B', 'Cambiar una ley no aparece como método de recopilación; las otras tres actividades sí se enumeran.', '{"paragraph":2,"quote":"draw on printed maps, collect coordinates with phones, or annotate photographs"}'::jsonb, '{"A":"Dibujar sobre mapas impresos se menciona expresamente.","C":"Las coordenadas pueden registrarse con teléfonos.","D":"Las fotografías pueden recibir anotaciones."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000071'::uuid, '60000000-0000-4000-8000-000000000013'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'What central idea does the passage develop?', '[{"id":"A","text":"Apprentices learn best when they receive no feedback."},{"id":"B","text":"Observation is the only useful part of workplace learning."},{"id":"C","text":"Apprenticeship builds practical judgment through guided participation, but its structure must also protect learners."},{"id":"D","text":"Formal standards and real work can never coexist."}]'::jsonb, 'C', 'El texto explica progresión, conocimiento tácito y retroalimentación, y termina incorporando protección y acceso justo.', '{"paragraph":4,"quote":"preserve situated practice while adding clear standards, fair compensation, and accessible routes for reporting problems"}'::jsonb, '{"A":"La retroalimentación evita que los errores se vuelvan hábitos.","B":"La participación y responsabilidad gradual complementan la observación.","D":"El reto es combinarlos, no declarar imposible su coexistencia."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000072'::uuid, '60000000-0000-4000-8000-000000000013'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 2, 2, 'Why does the author mention weighing ingredients and organizing tools?', '[{"id":"A","text":"To compare the profits of bakeries and workshops"},{"id":"B","text":"To show that apprentices should never advance"},{"id":"C","text":"To identify tasks that experts are unable to perform"},{"id":"D","text":"To illustrate useful beginner tasks with limited risk"}]'::jsonb, 'D', 'Los ejemplos concretan cómo un principiante participa en trabajo real sin asumir todavía las partes peligrosas.', '{"paragraph":1,"quote":"limited, low-risk tasks that contribute to real work"}'::jsonb, '{"A":"No se presentan datos económicos.","B":"La responsabilidad aumenta conforme crece la competencia.","C":"Los expertos pueden realizar esas tareas; se asignan por su valor formativo y menor riesgo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000073'::uuid, '60000000-0000-4000-8000-000000000013'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “tacit” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"understood through practice but not easily stated"},{"id":"B","text":"written in a detailed manual"},{"id":"C","text":"unrelated to physical work"},{"id":"D","text":"known only to customers"}]'::jsonb, 'A', 'Los ejemplos de tacto y vibración muestran juicios que el experto ejecuta pero que resultan difíciles de convertir en reglas.', '{"paragraph":2,"quote":"difficult to express as rules"}'::jsonb, '{"B":"Un manual detallado sería conocimiento explícito.","C":"Los juicios están integrados en la práctica física.","D":"Los poseen trabajadores expertos, no exclusivamente clientes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000074'::uuid, '60000000-0000-4000-8000-000000000013'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why should early mistakes have manageable consequences?', '[{"id":"A","text":"So mistakes can be repeated until they become habits."},{"id":"B","text":"So learners can receive correction without causing serious harm."},{"id":"C","text":"So experts no longer need to supervise work."},{"id":"D","text":"So workplaces can avoid explaining any standards."}]'::jsonb, 'B', 'El pasaje valora un entorno donde sea posible equivocarse y corregir antes de consolidar el error o producir daños mayores.', '{"paragraph":3,"quote":"provide timely, specific feedback before those mistakes become lasting habits"}'::jsonb, '{"A":"El objetivo es impedir que se conviertan en hábitos.","C":"La supervisión y retroalimentación siguen siendo centrales.","D":"Los estándares claros forman parte de los programas modernos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000075'::uuid, '60000000-0000-4000-8000-000000000013'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 3, 'The author’s attitude toward apprenticeship is best described as', '[{"id":"A","text":"uncritically nostalgic"},{"id":"B","text":"entirely opposed to workplace learning"},{"id":"C","text":"supportive but attentive to its risks and exclusions"},{"id":"D","text":"certain that unpaid labor is always necessary"}]'::jsonb, 'C', 'Se reconocen ventajas pedagógicas y, al mismo tiempo, se advierte contra idealizar arreglos injustos.', '{"paragraph":4,"quote":"Apprenticeship should not be romanticized."}'::jsonb, '{"A":"La crítica explícita impide una visión nostálgica sin reservas.","B":"El texto propone mejorar, no abandonar, el aprendizaje situado.","D":"La compensación se presenta como protección moderna."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000076'::uuid, '60000000-0000-4000-8000-000000000014'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 2, 'What is the author’s main purpose?', '[{"id":"A","text":"To argue that every sign should use identical wording"},{"id":"B","text":"To teach readers how to count letters on a sign"},{"id":"C","text":"To prove that permanent signs are always accurate"},{"id":"D","text":"To show that bilingual signage conveys practical information as well as social relationships"}]'::jsonb, 'D', 'El pasaje combina acceso, diseño, análisis de autoridad y límites institucionales para mostrar una función doble.', '{"paragraph":4,"quote":"one layer of a larger system of communication and power"}'::jsonb, '{"A":"Las traducciones pueden variar según lectores y contexto.","B":"El conteo de señales es un método parcial, no un objetivo en sí.","C":"La permanencia indica autoridad posible, no exactitud garantizada."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000077'::uuid, '60000000-0000-4000-8000-000000000014'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Why might a transit message be longer in one language?', '[{"id":"A","text":"Readers of that language may be less familiar with the transit system."},{"id":"B","text":"The language cannot be written in small letters."},{"id":"C","text":"Transit agencies are forbidden to translate directly."},{"id":"D","text":"The shorter language always has higher social status."}]'::jsonb, 'A', 'El segundo párrafo da como razón una familiaridad distinta con el sistema, lo que puede exigir más explicación.', '{"paragraph":2,"quote":"readers have different familiarity with the system"}'::jsonb, '{"B":"El tamaño de letras es una decisión separada.","C":"No se establece una prohibición general.","D":"La longitud no se equipara automáticamente con jerarquía."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000078'::uuid, '60000000-0000-4000-8000-000000000014'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 3, 2, 'Why can a simple count of signs be misleading?', '[{"id":"A","text":"Photographs cannot record written language."},{"id":"B","text":"Signs differ in visibility, permanence, authority, and intended audience."},{"id":"C","text":"Cities contain only temporary signs."},{"id":"D","text":"Every government sign uses two languages."}]'::jsonb, 'B', 'El autor contrasta diez avisos pequeños con una señal oficial permanente y pide atender a cualidades además de cantidad.', '{"paragraph":3,"quote":"numbers alone may mislead"}'::jsonb, '{"A":"Las fotografías son precisamente una herramienta de estudio.","C":"Se distinguen señales temporales y permanentes.","D":"No se afirma bilingüismo universal en señales gubernamentales."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000079'::uuid, '60000000-0000-4000-8000-000000000014'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 4, 2, 'The word “they” in paragraph 4 refers to', '[{"id":"A","text":"hospital patients"},{"id":"B","text":"multilingual directions"},{"id":"C","text":"signage policies"},{"id":"D","text":"neighborhoods"}]'::jsonb, 'C', 'El pronombre retoma el sujeto de la oración anterior: las políticas pueden ampliar acceso pero no garantizar trato igual.', '{"paragraph":4,"quote":"Signage policies can increase access, yet they"}'::jsonb, '{"A":"Los pacientes aparecen después como usuarios de atención.","B":"Las direcciones son un ejemplo de señalización, no el antecedente gramatical.","D":"Los barrios se mencionan en relación con letreros informales."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000080'::uuid, '60000000-0000-4000-8000-000000000014'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 3, 'Which statement best expresses the final paragraph?', '[{"id":"A","text":"Once signs are translated, no other language support is needed."},{"id":"B","text":"Unofficial signs have no practical value."},{"id":"C","text":"Hospitals should replace staff members with larger signs."},{"id":"D","text":"Visible multilingual information is useful, but equal communication also depends on institutional capacity and local practice."}]'::jsonb, 'D', 'Los ejemplos del hospital y el barrio muestran que las señales son solo una capa de un sistema más amplio.', '{"paragraph":4,"quote":"they cannot by themselves guarantee equal treatment"}'::jsonb, '{"A":"La falta de personal competente demuestra que la traducción visual no basta.","B":"El aviso manuscrito puede ser muy útil.","C":"El texto reclama comunicación humana además de señalización."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000081'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'Which statement best captures the central argument of the passage?', '[{"id":"A","text":"A census requires conventions, multiple methods, and transparent corrections to represent a changing population."},{"id":"B","text":"A census is a simple total that requires no definitions."},{"id":"C","text":"Online forms have eliminated all population undercounts."},{"id":"D","text":"Census categories should never change over time."}]'::jsonb, 'A', 'El texto desarrolla dificultades de residencia, recolección, omisión, estimación y categorías antes de defender transparencia.', '{"paragraph":7,"quote":"a carefully designed one can provide a shared reference while making its limitations visible"}'::jsonb, '{"B":"Las reglas de residencia muestran que contar exige definiciones.","C":"Persisten brechas incluso con métodos digitales.","D":"Las categorías cambian con la sociedad y las necesidades."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000082'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'Why do census systems establish a reference date?', '[{"id":"A","text":"To guarantee that nobody travels that day"},{"id":"B","text":"To apply residence rules consistently to a population that is always changing"},{"id":"C","text":"To prevent students from having an address"},{"id":"D","text":"To replace all household responses with estimates"}]'::jsonb, 'B', 'La fecha y el concepto de residencia crean una convención común para casos que podrían asociarse con varios lugares.', '{"paragraph":2,"quote":"make separate responses more comparable"}'::jsonb, '{"A":"Una fecha de referencia no detiene los desplazamientos.","C":"Los estudiantes ilustran ambigüedad, no ausencia de domicilio.","D":"Las estimaciones se usan para evaluar omisiones después."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000083'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “plausibly” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"permanently"},{"id":"B","text":"secretly"},{"id":"C","text":"reasonably"},{"id":"D","text":"incorrectly"}]'::jsonb, 'C', 'Los ejemplos pueden vincularse con más de una dirección de manera razonable, por eso se necesitan reglas convencionales.', '{"paragraph":2,"quote":"could plausibly be associated with more than one address"}'::jsonb, '{"A":"La asociación puede ser temporal.","B":"El problema no depende de ocultar información.","D":"Más de una dirección puede ser válida según el criterio usado."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000084'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 2, 'Why does the author describe online responses followed by visits?', '[{"id":"A","text":"To show that enumerators no longer perform any work"},{"id":"B","text":"To argue that paper forms count people twice by design"},{"id":"C","text":"To identify the only method used in remote areas"},{"id":"D","text":"To illustrate how agencies combine collection methods"}]'::jsonb, 'D', 'La secuencia ejemplifica un enfoque escalonado que combina canales y concentra seguimiento donde falta respuesta.', '{"paragraph":3,"quote":"Using several sources can reduce cost"}'::jsonb, '{"A":"Los trabajadores siguen visitando direcciones sin respuesta.","B":"La duplicación es un riesgo que se intenta prevenir, no un objetivo.","C":"No se limita el ejemplo a regiones remotas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000085'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 3, 'Why can a high national response rate give a misleading impression?', '[{"id":"A","text":"It can conceal severe undercounting concentrated in particular groups or places."},{"id":"B","text":"It proves that every community has the same participation."},{"id":"C","text":"It means that no statistical models are needed."},{"id":"D","text":"It counts every mobile person more than once."}]'::jsonb, 'A', 'El promedio nacional puede ser alto aunque comunidades específicas tengan barreras y ausencias sistemáticas.', '{"paragraph":4,"quote":"coexist with serious gaps in particular communities"}'::jsonb, '{"B":"El párrafo afirma una distribución desigual.","C":"Los modelos pueden seguir siendo necesarios para medir brechas.","D":"La movilidad puede producir omisión o duplicación, pero no necesariamente en todos los casos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000086'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 3, 'All of the following are mentioned as possible barriers to census participation EXCEPT', '[{"id":"A","text":"frequent movement"},{"id":"B","text":"having a permanent government office nearby"},{"id":"C","text":"language differences"},{"id":"D","text":"distrust about data sharing"}]'::jsonb, 'B', 'Una oficina cercana no aparece entre las barreras; sí se mencionan movilidad, idioma, desconfianza y distancia.', '{"paragraph":4,"quote":"Language barriers, distrust of government, or fear that information will be shared"}'::jsonb, '{"A":"Mudarse con frecuencia puede hacer perder formularios y visitas.","C":"Las barreras lingüísticas reducen participación.","D":"El temor al intercambio de datos se identifica directamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000087'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 7, 3, 'How does the author present statistical adjustment?', '[{"id":"A","text":"As unquestionably perfect"},{"id":"B","text":"As a deliberate attempt to hide all direct responses"},{"id":"C","text":"As contested but potentially necessary when direct counts have known biases"},{"id":"D","text":"As irrelevant to representation and funding"}]'::jsonb, 'C', 'El pasaje reconoce la controversia y también el costo de dejar omisiones sistemáticas sin corregir.', '{"paragraph":5,"quote":"Adjustment is controversial"}'::jsonb, '{"A":"Los modelos estiman y conservan incertidumbre.","B":"La comparación parte de respuestas directas y una encuesta independiente.","D":"El texto vincula expresamente omisión con representación y recursos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000088'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 8, 3, 'The phrase “these gaps” in paragraph 5 refers to', '[{"id":"A","text":"differences between paper colors"},{"id":"B","text":"distances between legislative seats"},{"id":"C","text":"changes in school schedules"},{"id":"D","text":"patterns of people being missed or unevenly represented"}]'::jsonb, 'D', 'La expresión retoma la subrepresentación desigual descrita en el párrafo anterior.', '{"paragraph":5,"quote":"Agencies attempt to measure these gaps"}'::jsonb, '{"A":"No se analizan colores de formularios.","B":"Los escaños usan resultados, pero la distancia entre ellos no es una brecha de conteo.","C":"Los horarios escolares no se discuten."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000089'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 9, 3, 'Which statement best expresses the problem discussed in paragraph 6?', '[{"id":"A","text":"Changes in census categories can improve visibility while making historical comparison harder."},{"id":"B","text":"New categories always prove that a population suddenly appeared."},{"id":"C","text":"Earlier census data become completely useless after wording changes."},{"id":"D","text":"Respondents never change how willing they are to answer."}]'::jsonb, 'A', 'El párrafo plantea una ganancia de medición y una dificultad interpretativa entre cambio social, definición y respuesta.', '{"paragraph":6,"quote":"make previously invisible experiences measurable, but it can complicate comparison"}'::jsonb, '{"B":"Una nueva medición no demuestra por sí sola aparición repentina.","C":"La comparación se complica, pero no se vuelve imposible.","D":"La voluntad de responder es una explicación considerada."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000090'::uuid, '60000000-0000-4000-8000-000000000015'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'Which description best matches the structure of the passage?', '[{"id":"A","text":"It lists census years in chronological order."},{"id":"B","text":"It moves from the basic counting problem through methods and biases to the institutional consequences of census design."},{"id":"C","text":"It compares only two online survey companies."},{"id":"D","text":"It begins with a conclusion and then rejects every use of census data."}]'::jsonb, 'B', 'La progresión va de definición y residencia a recolección, omisión, categorías y confianza pública.', '{"paragraph":7,"quote":"The census is therefore both a measurement and an institution."}'::jsonb, '{"A":"No se ofrece una cronología de años censales.","C":"Las agencias y métodos son generales, no empresas específicas.","D":"La conclusión conserva el valor del censo como referencia compartida."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000091'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'What central claim does the passage make about irrigation systems?', '[{"id":"A","text":"Concrete canals automatically produce equal water access."},{"id":"B","text":"Traditional rules are always fairer than written procedures."},{"id":"C","text":"Their success depends on legitimate social rules as well as physical engineering."},{"id":"D","text":"Water schedules matter only when rainfall is abundant."}]'::jsonb, 'C', 'Cada sección relaciona infraestructura con turnos, trabajo, monitoreo, desigualdad, intervención y adaptación legítima.', '{"paragraph":1,"quote":"both a physical structure and a schedule of obligations"}'::jsonb, '{"A":"El concreto puede causar efectos ignorados y no resuelve legitimidad.","B":"Las tradiciones pueden reproducir desigualdad.","D":"Los horarios son especialmente críticos en regiones secas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000092'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'What disadvantage of allocating water by fixed hours is mentioned?', '[{"id":"A","text":"Hours cannot be measured."},{"id":"B","text":"Every field receives too much water."},{"id":"C","text":"The rule prevents any public schedule."},{"id":"D","text":"Changing flow can cause equal periods to deliver unequal amounts."}]'::jsonb, 'D', 'El segundo párrafo contrasta facilidad de medir tiempo con variación del volumen cuando cambia el caudal.', '{"paragraph":2,"quote":"equal hours do not deliver equal volumes when flow changes"}'::jsonb, '{"A":"El tiempo se describe como más fácil de medir.","B":"El resultado depende del flujo y no siempre es exceso.","C":"Los turnos pueden registrarse públicamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000093'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “proportional” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"determined in relation to an amount or share"},{"id":"B","text":"secretly assigned"},{"id":"C","text":"identical for every person"},{"id":"D","text":"unrelated to land or rights"}]'::jsonb, 'A', 'La contribución puede variar según superficie, derechos o posición, es decir, guardar relación con una medida.', '{"paragraph":3,"quote":"proportional to land area, water rights, or household status"}'::jsonb, '{"B":"La organización es comunitaria y observable.","C":"La proporcionalidad permite cargas diferentes.","D":"La frase enumera precisamente los factores relacionados."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000094'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 3, 'Why can visible gates and public records reduce the need for frequent punishment?', '[{"id":"A","text":"They prevent upstream farms from using any water."},{"id":"B","text":"They make behavior observable and violations easier to anticipate or resolve."},{"id":"C","text":"They eliminate every disagreement about rules."},{"id":"D","text":"They allow inspectors to remain permanently absent."}]'::jsonb, 'B', 'La observabilidad favorece cumplimiento y tratamiento temprano de disputas sin depender solo de sanciones constantes.', '{"paragraph":4,"quote":"When rules and actions are observable"}'::jsonb, '{"A":"Los usuarios río arriba conservan turnos legítimos.","C":"El texto habla de abordar disputas, no de eliminarlas.","D":"Existen guardias o inspectores aunque su rotación varíe."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000095'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 3, 'How does the author treat community traditions?', '[{"id":"A","text":"As perfect systems that outsiders should never question"},{"id":"B","text":"As obstacles that must always be replaced by technology"},{"id":"C","text":"As valuable sources of coordination that still require critical examination"},{"id":"D","text":"As practices unrelated to power"}]'::jsonb, 'C', 'Se reconocen cooperación y duración, pero también exclusiones y la posibilidad de reformas.', '{"paragraph":5,"quote":"Not all traditions are equitable."}'::jsonb, '{"A":"La desigualdad heredada exige revisión.","B":"La intervención útil comprende el sistema en vez de sustituirlo automáticamente.","D":"El texto analiza explícitamente voz e influencia."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000096'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 3, 'All of the following are described as forms of canal maintenance contribution EXCEPT', '[{"id":"A","text":"removing sediment"},{"id":"B","text":"repairing canal walls"},{"id":"C","text":"providing food when unable to work"},{"id":"D","text":"writing national weather forecasts"}]'::jsonb, 'D', 'El pronóstico nacional no aparece como contribución al mantenimiento; las otras acciones sí.', '{"paragraph":3,"quote":"remove sediment, repair walls, and clear plants"}'::jsonb, '{"A":"Retirar sedimento es una tarea colectiva.","B":"Reparar paredes ocurre antes de la temporada.","C":"Alguien puede aportar comida o dinero en lugar de trabajo físico."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000097'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 2, 7, 3, 'Why does the author mention seepage replenishing wells?', '[{"id":"A","text":"To show that an apparently inefficient feature can provide benefits outside the canal."},{"id":"B","text":"To prove that all canal leakage should increase"},{"id":"C","text":"To explain why concrete is impossible to manufacture"},{"id":"D","text":"To show that wells cause every irrigation dispute"}]'::jsonb, 'A', 'El ejemplo advierte que una mejora técnica aislada puede eliminar servicios hídricos o ecológicos no considerados.', '{"paragraph":6,"quote":"seepage replenished wells or supported plants"}'::jsonb, '{"B":"El texto pide evaluar efectos, no maximizar pérdidas.","C":"El problema es adecuación social y ecológica, no fabricación.","D":"Los conflictos tienen múltiples causas y no se atribuyen a pozos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000098'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 8, 3, 'The phrase “These arrangements” in paragraph 3 refers to', '[{"id":"A","text":"the timing of snowmelt"},{"id":"B","text":"the different ways users contribute labor, money, or food"},{"id":"C","text":"the installation of concrete gates"},{"id":"D","text":"the exclusion of tenants"}]'::jsonb, 'B', 'El demostrativo resume las formas de participación y sustitución de trabajo descritas inmediatamente antes.', '{"paragraph":3,"quote":"These arrangements convert an individual need for water into repeated cooperation."}'::jsonb, '{"A":"El deshielo se discute al final.","C":"Las compuertas externas aparecen varios párrafos después.","D":"La exclusión se presenta como problema distinto."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000099'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 9, 3, 'Which statement best expresses the final sentence?', '[{"id":"A","text":"Engineering is unnecessary whenever rules change."},{"id":"B","text":"Legitimate processes guarantee that more water will arrive."},{"id":"C","text":"Adaptation requires users to trust the way new rules are made, not merely access to technical solutions."},{"id":"D","text":"Users should preserve every old schedule without discussion."}]'::jsonb, 'C', 'La conclusión distingue disponibilidad técnica de legitimidad del proceso institucional de cambio.', '{"paragraph":7,"quote":"depends not only on available engineering but on whether users consider the process for changing rules legitimate"}'::jsonb, '{"A":"La ingeniería sigue siendo relevante, pero no suficiente.","B":"La legitimidad facilita adaptación sin crear agua adicional.","D":"El clima cambiante puede exigir revisar horarios anteriores."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000100'::uuid, '60000000-0000-4000-8000-000000000016'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'How does paragraph 6 function in the passage?', '[{"id":"A","text":"It introduces a single solution that works in every region."},{"id":"B","text":"It changes the topic from water to urban libraries."},{"id":"C","text":"It argues that leakage has no consequences."},{"id":"D","text":"It warns against both purely technical intervention and uncritical preservation of tradition."}]'::jsonb, 'D', 'El párrafo critica tanto proyectos que ignoran relaciones locales como la idealización de prácticas ineficientes o injustas.', '{"paragraph":6,"quote":"Conversely, romanticizing traditional practice can preserve avoidable losses and unequal rules."}'::jsonb, '{"A":"La conclusión pide comprender cada contexto.","B":"El tema sigue siendo coordinación del riego.","C":"La filtración puede alimentar pozos y plantas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000101'::uuid, '60000000-0000-4000-8000-000000000017'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 1, 'What discovery about Roman concrete is emphasized in the passage?', '[{"id":"A","text":"Lime-rich fragments once considered defects may help seal cracks."},{"id":"B","text":"All Roman concrete was poured in dry desert conditions."},{"id":"C","text":"Modern salt water cannot damage concrete."},{"id":"D","text":"Roman builders removed every mineral from their mixtures."}]'::jsonb, 'A', 'El núcleo del texto es la reinterpretación de fragmentos de cal como posibles agentes de autorreparación.', '{"paragraph":2,"quote":"they can contribute to self-repair"}'::jsonb, '{"B":"El texto menciona colocación bajo agua marina.","C":"Se afirma que el concreto moderno puede agrietarse con sal.","D":"Los minerales se forman dentro de las grietas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000102'::uuid, '60000000-0000-4000-8000-000000000017'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'What happens after water reaches a lime-rich fragment?', '[{"id":"A","text":"The entire structure becomes liquid."},{"id":"B","text":"Calcium-rich material dissolves and forms minerals in the crack."},{"id":"C","text":"Volcanic ash is removed from the harbor."},{"id":"D","text":"Wooden forms grow around the crack."}]'::jsonb, 'B', 'El segundo párrafo describe una secuencia de disolución y posterior precipitación mineral.', '{"paragraph":2,"quote":"calcium-rich material dissolves and later forms new minerals"}'::jsonb, '{"A":"El cambio es local y no licua la estructura.","C":"La ceniza forma parte de la mezcla y no se extrae.","D":"Los moldes se usaron durante construcción, no crecen."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000103'::uuid, '60000000-0000-4000-8000-000000000017'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 1, 'The word “dismissed” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"carefully measured"},{"id":"B","text":"placed underwater"},{"id":"C","text":"rejected as unimportant"},{"id":"D","text":"copied exactly"}]'::jsonb, 'C', 'Antes se consideraban señal de mezcla descuidada y no una característica funcional digna de atención.', '{"paragraph":2,"quote":"were once dismissed as evidence of careless mixing"}'::jsonb, '{"A":"La medición microscópica pertenece a estudios recientes.","B":"La colocación bajo agua describe construcción portuaria.","D":"No se habla de copiar los fragmentos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000104'::uuid, '60000000-0000-4000-8000-000000000017'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why has the interpretation of the lime fragments changed?', '[{"id":"A","text":"Historians discovered that Romans never used lime."},{"id":"B","text":"Every modern concrete recipe now copies a Roman one."},{"id":"C","text":"The fragments have disappeared from old structures."},{"id":"D","text":"New microscopic evidence suggests a useful mechanism that was previously overlooked."}]'::jsonb, 'D', 'La observación de interacción entre agua, calcio y grietas ofrece una función que antes no se reconocía.', '{"paragraph":2,"quote":"Researchers now propose that they can contribute to self-repair."}'::jsonb, '{"A":"La cal era un ingrediente explícito.","B":"No se afirma adopción universal moderna.","C":"Los fragmentos siguen siendo objeto de estudio."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000105'::uuid, '60000000-0000-4000-8000-000000000017'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 2, 'How does the author qualify the self-repair explanation?', '[{"id":"A","text":"It is promising but limited and not identical across all Roman concrete."},{"id":"B","text":"It proves that Roman structures can never be damaged."},{"id":"C","text":"It applies only to modern concrete."},{"id":"D","text":"It is described as a deliberate historical fraud."}]'::jsonb, 'A', 'El cierre reconoce límites del daño reparable y variación de recetas antes de señalar la importancia del hallazgo.', '{"paragraph":3,"quote":"cannot repair unlimited damage, and Roman recipes varied widely"}'::jsonb, '{"B":"Se niega explícitamente reparación ilimitada.","C":"El fenómeno se estudia en concreto romano.","D":"No se atribuye engaño a los constructores."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000106'::uuid, '60000000-0000-4000-8000-000000000018'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 1, 'What does the passage explain about relay networks?', '[{"id":"A","text":"How ordinary citizens received free mail every day"},{"id":"B","text":"How they accelerated official communication through organized exchanges"},{"id":"C","text":"Why horses could travel forever without rest"},{"id":"D","text":"How electronic messages replaced sealed documents"}]'::jsonb, 'B', 'El texto describe estaciones, cambios de caballo o mensajero, recursos y uso político principalmente oficial.', '{"paragraph":2,"quote":"no single animal or person had to complete the entire journey without rest"}'::jsonb, '{"A":"El acceso ordinario no estaba siempre permitido.","C":"La ventaja consistía en reemplazar animales cansados.","D":"El período descrito precede la comunicación electrónica."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000107'::uuid, '60000000-0000-4000-8000-000000000018'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'What could an authorized courier do at a relay station?', '[{"id":"A","text":"Print a newspaper for local residents"},{"id":"B","text":"Build a new political capital"},{"id":"C","text":"Exchange a tired horse for a rested one"},{"id":"D","text":"Send an electronic copy of the message"}]'::jsonb, 'C', 'El primer párrafo enumera el cambio de caballo y la entrega a otro jinete como operaciones del relevo.', '{"paragraph":1,"quote":"exchange a tired horse for a rested one"}'::jsonb, '{"A":"No se mencionan periódicos.","B":"Las estaciones conectaban con el centro; no creaban capitales.","D":"La transmisión era física."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000108'::uuid, '60000000-0000-4000-8000-000000000018'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 3, 1, 'The word “these” in paragraph 2 refers to', '[{"id":"A","text":"distant political centers"},{"id":"B","text":"ordinary private letters"},{"id":"C","text":"future railway schedules"},{"id":"D","text":"station animals, food, workers, and related resources"}]'::jsonb, 'D', 'El demostrativo retoma los recursos que un viajero debía estar autorizado a utilizar.', '{"paragraph":2,"quote":"allowed officials to use these resources"}'::jsonb, '{"A":"Los centros son destinos de la red, no recursos de estación.","B":"La correspondencia común podía estar excluida.","C":"Los ferrocarriles son posteriores."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000109'::uuid, '60000000-0000-4000-8000-000000000018'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 4, 1, 'Which activity was NOT identified as a main purpose of the relay network?', '[{"id":"A","text":"Delivering personal letters for all residents"},{"id":"B","text":"transmitting government orders"},{"id":"C","text":"reporting conditions in distant regions"},{"id":"D","text":"moving officials"}]'::jsonb, 'A', 'El último párrafo limita el sistema a funciones administrativas y aclara que no siempre aceptaba correspondencia ordinaria.', '{"paragraph":3,"quote":"not always open to ordinary correspondence"}'::jsonb, '{"B":"Las órdenes forman parte de la lista administrativa.","C":"Los informes de condiciones se mencionan expresamente.","D":"El movimiento de funcionarios también era una función."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000110'::uuid, '60000000-0000-4000-8000-000000000018'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 2, 'Why does the author call access to speed “a form of power”?', '[{"id":"A","text":"Fast horses automatically became rulers."},{"id":"B","text":"Those authorized to use the network could act on distant information sooner than others."},{"id":"C","text":"Every station controlled its own independent state."},{"id":"D","text":"Ordinary correspondence traveled faster than official orders."}]'::jsonb, 'B', 'El privilegio de la red permitía al gobierno transmitir información y decisiones con una rapidez no disponible para todos.', '{"paragraph":3,"quote":"access to that speed was itself a form of power"}'::jsonb, '{"A":"Los animales eran recursos, no autoridades.","C":"Las estaciones integraban una red política.","D":"El acceso oficial era el prioritario."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000111'::uuid, '60000000-0000-4000-8000-000000000019'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Which idea about the spread of paper is central to the passage?', '[{"id":"A","text":"Paper replaced all other writing materials as soon as it appeared."},{"id":"B","text":"The same plant fibers were used in every region."},{"id":"C","text":"Paper spread through gradual adaptation and gained importance within supporting institutions."},{"id":"D","text":"Paper alone caused universal literacy."}]'::jsonb, 'C', 'El texto combina transmisión técnica, adaptación de materias primas, convivencia de soportes y condiciones institucionales.', '{"paragraph":4,"quote":"its historical effect depended on the institutions that used it"}'::jsonb, '{"A":"Papiro y pergamino continuaron utilizándose.","B":"Los artesanos usaron materiales locales distintos.","D":"El cierre niega que el material por sí solo creara una sociedad alfabetizada."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000112'::uuid, '60000000-0000-4000-8000-000000000019'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Why did some workshops use linen and hemp rags?', '[{"id":"A","text":"Rags eliminated the need to separate fibers."},{"id":"B","text":"Parchment could not be erased."},{"id":"C","text":"Water power was forbidden in China."},{"id":"D","text":"Locally available materials differed from those used in China."}]'::jsonb, 'D', 'El segundo párrafo explica que los artesanos adaptaron la materia prima a las condiciones locales.', '{"paragraph":2,"quote":"adapted raw materials to local conditions"}'::jsonb, '{"A":"La fabricación aún requería preparar fibras.","B":"El pergamino podía borrarse y reutilizarse.","C":"No se plantea una prohibición de energía hidráulica."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000113'::uuid, '60000000-0000-4000-8000-000000000019'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “suspend” in paragraph 1 is closest in meaning to', '[{"id":"A","text":"disperse throughout a liquid"},{"id":"B","text":"hang a finished book from a wall"},{"id":"C","text":"stop production permanently"},{"id":"D","text":"write symbols on dry paper"}]'::jsonb, 'A', 'Durante la fabricación, las fibras se distribuyen en agua antes de levantarlas con una malla.', '{"paragraph":1,"quote":"suspend them in water"}'::jsonb, '{"B":"No se describe almacenamiento de libros.","C":"La secuencia continúa después de esta acción.","D":"La escritura sucede tras fabricar y secar la hoja."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000114'::uuid, '60000000-0000-4000-8000-000000000019'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 2, 'Why does the author discuss papyrus and parchment?', '[{"id":"A","text":"To prove that paper was less portable than bamboo"},{"id":"B","text":"To show that adoption of paper was gradual and depended on particular uses"},{"id":"C","text":"To explain how printing was invented in China"},{"id":"D","text":"To claim that every institution chose the same material"}]'::jsonb, 'B', 'La permanencia de otros soportes demuestra selección según costo, prestigio, disponibilidad y finalidad.', '{"paragraph":3,"quote":"did not immediately replace every writing surface"}'::jsonb, '{"A":"El primer párrafo caracteriza el papel como ligero.","C":"La impresión se menciona después como otra tecnología.","D":"Las instituciones podían tomar decisiones diferentes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000115'::uuid, '60000000-0000-4000-8000-000000000019'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 3, 'Which statement best expresses the conclusion?', '[{"id":"A","text":"Low paper prices automatically taught everyone to read."},{"id":"B","text":"Institutions had no influence on written communication."},{"id":"C","text":"Cheaper writing material mattered most where social and economic systems enabled people to use it."},{"id":"D","text":"Printing made schools and trade networks unnecessary."}]'::jsonb, 'C', 'La reducción de costos fue una condición útil, pero su efecto dependió de escuelas, demanda, productores y redes.', '{"paragraph":4,"quote":"Paper lowered some production costs, but its historical effect depended on the institutions that used it."}'::jsonb, '{"A":"El pasaje rechaza una relación automática con alfabetización universal.","B":"Las instituciones son el condicionante central.","D":"Escuelas y comercio aparecen junto con impresión, no como sustituidos por ella."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000116'::uuid, '60000000-0000-4000-8000-000000000020'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 2, 'What does the author mainly explain about Pacific navigation?', '[{"id":"A","text":"It relied entirely on the largest visible wave."},{"id":"B","text":"It became possible only after magnetic compasses arrived."},{"id":"C","text":"It used one bird species as a guaranteed sign of land."},{"id":"D","text":"It combined multiple environmental cues with trained memory and bodily experience."}]'::jsonb, 'D', 'El pasaje recorre señales celestes, oceánicas y terrestres, además del aprendizaje práctico que las integra.', '{"paragraph":4,"quote":"both an intellectual system and a bodily skill"}'::jsonb, '{"A":"Varias olas podían cruzarse y la mayor no bastaba.","B":"Se destaca navegación sin compás magnético.","C":"Ninguna señal aislada garantizaba tierra."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000117'::uuid, '60000000-0000-4000-8000-000000000020'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'How could ocean swells assist when stars were hidden?', '[{"id":"A","text":"They could retain information about winds beyond the cloudy area."},{"id":"B","text":"They made all clouds disappear."},{"id":"C","text":"They always pointed directly toward the nearest island."},{"id":"D","text":"They produced a magnetic field around the canoe."}]'::jsonb, 'A', 'El segundo párrafo señala que oleajes largos conservan información sobre vientos distantes aun con cielo cubierto.', '{"paragraph":2,"quote":"long ocean swells could preserve information about distant winds"}'::jsonb, '{"B":"El oleaje no controla las nubes.","C":"Interpretar patrones no equivale a señalar siempre la isla más cercana.","D":"No se atribuye magnetismo al oleaje."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000118'::uuid, '60000000-0000-4000-8000-000000000020'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 3, 2, 'Which of the following is NOT mentioned as a possible sign of nearby land?', '[{"id":"A","text":"seabirds returning in the evening"},{"id":"B","text":"A sudden change in the writing on a chart"},{"id":"C","text":"clouds gathering above land"},{"id":"D","text":"a green tint beneath a cloud"}]'::jsonb, 'B', 'Las cartas modernas no forman parte del sistema descrito; las otras señales se enumeran en el tercer párrafo.', '{"paragraph":3,"quote":"Signs of land became important near the end of a voyage."}'::jsonb, '{"A":"El regreso nocturno de ciertas aves puede indicar islas.","C":"Algunas nubes se forman sobre tierra.","D":"La luz reflejada de una laguna puede teñir una nube."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000119'::uuid, '60000000-0000-4000-8000-000000000020'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why was experience necessary for interpreting swells?', '[{"id":"A","text":"Swells occurred only once in a navigator’s lifetime."},{"id":"B","text":"A canoe could not move when waves were present."},{"id":"C","text":"Several wave patterns could overlap and had to be distinguished."},{"id":"D","text":"Wind had no relationship to wave direction."}]'::jsonb, 'C', 'Con múltiples oleajes simultáneos, reconocer el patrón informativo exige comparación aprendida.', '{"paragraph":2,"quote":"Several swells might cross at once"}'::jsonb, '{"A":"Los viajes y la práctica eran repetidos.","B":"El movimiento de la canoa era una fuente de sensación.","D":"Los oleajes preservaban información sobre vientos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000120'::uuid, '60000000-0000-4000-8000-000000000020'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 2, 'What broader point does the final paragraph make about navigational knowledge?', '[{"id":"A","text":"Navigation was taught only through written examinations."},{"id":"B","text":"Bodily sensation made star knowledge unnecessary."},{"id":"C","text":"Learners avoided feeling the movement of the canoe."},{"id":"D","text":"Navigational knowledge included memorized systems and sensitivity developed through physical practice."}]'::jsonb, 'D', 'La conclusión une nombres y secuencias con percepción corporal afinada en viajes.', '{"paragraph":4,"quote":"both an intellectual system and a bodily skill refined through practice"}'::jsonb, '{"A":"La enseñanza se apoyaba en memoria y práctica, no solo escritura.","B":"Las fuentes de información se combinaban.","C":"Sentir el movimiento era un ejercicio formativo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000121'::uuid, '60000000-0000-4000-8000-000000000021'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Why were urban coffeehouses historically important according to the passage?', '[{"id":"A","text":"They brought printed information and social networks together."},{"id":"B","text":"They guaranteed equal political power to every resident."},{"id":"C","text":"They prevented rumors from spreading."},{"id":"D","text":"They served only as quiet places to drink coffee."}]'::jsonb, 'A', 'El texto destaca la combinación de impresos, conversación, negocios y redes, con límites de acceso.', '{"paragraph":3,"quote":"connected print, conversation, business, and sociability"}'::jsonb, '{"B":"La participación estaba condicionada y no era plenamente igual.","C":"La rapidez también difundía rumores.","D":"Las conversaciones y noticias eran funciones centrales."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000122'::uuid, '60000000-0000-4000-8000-000000000021'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Where were merchants especially likely to gather?', '[{"id":"A","text":"Inside remote farming villages"},{"id":"B","text":"Near exchanges and docks"},{"id":"C","text":"Only in government offices"},{"id":"D","text":"At stations for relay horses"}]'::jsonb, 'B', 'El segundo párrafo asocia reputaciones y clientelas con ubicaciones, incluidos intercambios y muelles.', '{"paragraph":2,"quote":"Merchants gathered near exchanges and docks"}'::jsonb, '{"A":"El contexto es urbano.","C":"Los cafés eran espacios distintos de oficinas oficiales.","D":"Las estaciones postales pertenecen a otra red."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000123'::uuid, '60000000-0000-4000-8000-000000000021'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “favored” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"closed"},{"id":"B","text":"financed"},{"id":"C","text":"preferred"},{"id":"D","text":"measured"}]'::jsonb, 'C', 'Escritores y grupos políticos tendían a elegir ciertos locales frente a otros.', '{"paragraph":2,"quote":"favored other locations"}'::jsonb, '{"A":"Los locales podían ser vigilados, pero «favored» no significa cerrar.","B":"No se afirma que financiaran el establecimiento.","D":"No expresa una operación de medición."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000124'::uuid, '60000000-0000-4000-8000-000000000021'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why might governments have monitored coffeehouses?', '[{"id":"A","text":"Coffee made printed pages impossible to read."},{"id":"B","text":"Every customer worked for the government."},{"id":"C","text":"Coffeehouses prevented merchants from trading."},{"id":"D","text":"Rapid discussion networks could circulate politically sensitive ideas or rumors."}]'::jsonb, 'D', 'La velocidad de noticias y rumores, junto con debate político, explica el interés de vigilancia.', '{"paragraph":2,"quote":"governments sometimes watched coffeehouses or attempted to restrict discussion"}'::jsonb, '{"A":"Los materiales impresos circulaban ampliamente.","B":"Los clientes incluían múltiples grupos.","C":"Los comerciantes usaban estos espacios vinculados con negocios."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000125'::uuid, '60000000-0000-4000-8000-000000000021'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 3, 'How does the author treat the idea that coffeehouses were democratic spaces?', '[{"id":"A","text":"With caution, because participation was socially limited"},{"id":"B","text":"With complete acceptance"},{"id":"C","text":"As impossible because no conversation occurred"},{"id":"D","text":"As irrelevant to their history"}]'::jsonb, 'A', 'El autor corrige una generalización: reconoce intercambio público pero enumera barreras de acceso.', '{"paragraph":3,"quote":"misleading to describe every coffeehouse as a fully democratic public sphere"}'::jsonb, '{"B":"La afirmación se matiza explícitamente.","C":"La conversación era una actividad principal.","D":"La inclusión limitada es parte del análisis histórico."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000126'::uuid, '60000000-0000-4000-8000-000000000022'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'What problem and response does the passage primarily discuss?', '[{"id":"A","text":"The moon has stopped changing its phases."},{"id":"B","text":"Calendars use different correction systems because astronomical cycles do not divide evenly."},{"id":"C","text":"All societies use the same definition of a month."},{"id":"D","text":"Calendar reform affects astronomy but no social institution."}]'::jsonb, 'B', 'El pasaje parte del desajuste, compara sistemas, explica días intercalares y termina con consecuencias sociales.', '{"paragraph":1,"quote":"astronomical cycles used to define those units do not fit neatly together"}'::jsonb, '{"A":"El ciclo lunar sigue siendo la base de varios calendarios.","C":"Se describen sistemas lunar, solar y lunisolar.","D":"La reforma afecta contratos, impuestos y celebraciones."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000127'::uuid, '60000000-0000-4000-8000-000000000022'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'How does a lunisolar calendar keep seasonal events in a similar part of the year?', '[{"id":"A","text":"It shortens every day."},{"id":"B","text":"It ignores lunar months completely."},{"id":"C","text":"It occasionally inserts an extra month."},{"id":"D","text":"It removes all agricultural markers."}]'::jsonb, 'C', 'El segundo párrafo señala la intercalación periódica de un mes para realinear meses lunares y estaciones.', '{"paragraph":2,"quote":"periodically insert an additional month"}'::jsonb, '{"A":"La duración del día no cambia.","B":"El sistema conserva meses lunares.","D":"Los marcadores agrícolas son una razón para mantener alineación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000128'::uuid, '60000000-0000-4000-8000-000000000022'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “drift” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"become immediately identical"},{"id":"B","text":"stop being counted"},{"id":"C","text":"change names every day"},{"id":"D","text":"move gradually out of alignment"}]'::jsonb, 'D', 'Un error pequeño acumulado durante siglos desplaza lentamente las fechas respecto de eventos solares.', '{"paragraph":3,"quote":"dates drift slowly relative to equinoxes and solstices"}'::jsonb, '{"A":"El resultado es desalineación, no identidad.","B":"Las fechas continúan contándose.","C":"No se describe un cambio diario de nombres."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000129'::uuid, '60000000-0000-4000-8000-000000000022'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why can a very small error in year length matter?', '[{"id":"A","text":"Repeated annually, it accumulates into a visible seasonal shift."},{"id":"B","text":"It changes the length of the moon’s orbit immediately."},{"id":"C","text":"It prevents anyone from using contracts."},{"id":"D","text":"It adds a full month every morning."}]'::jsonb, 'A', 'El tercer párrafo explica acumulación: una diferencia mínima anual se vuelve perceptible con el paso de siglos.', '{"paragraph":3,"quote":"Over centuries, a small annual error becomes noticeable."}'::jsonb, '{"B":"El calendario no modifica la órbita lunar.","C":"Los contratos son afectados por reformas, no imposibilitados por todo error.","D":"La escala descrita es anual y secular."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000130'::uuid, '60000000-0000-4000-8000-000000000022'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 5, 2, 'Why does the author mention taxes, contracts, and anniversaries?', '[{"id":"A","text":"To list astronomical objects"},{"id":"B","text":"To show that calendar changes have practical and social consequences"},{"id":"C","text":"To prove that leap days are unnecessary"},{"id":"D","text":"To explain how lunar months are measured"}]'::jsonb, 'B', 'Los ejemplos amplían la reforma más allá del cálculo astronómico hacia instituciones y hábitos.', '{"paragraph":4,"quote":"Changing a rule can alter religious observances, tax periods, contracts, and anniversaries."}'::jsonb, '{"A":"Son actividades humanas, no cuerpos celestes.","C":"La necesidad de corrección solar ya fue explicada.","D":"La medición lunar se presenta al inicio, no mediante contratos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000131'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'What central point does the passage make about archaeological refuse?', '[{"id":"A","text":"Trash deposits provide exact photographs of every household."},{"id":"B","text":"Only valuable objects can reveal inequality."},{"id":"C","text":"Discarded material can reveal ordinary life, but only after its formation and context are carefully analyzed."},{"id":"D","text":"Archaeologists avoid using small biological remains."}]'::jsonb, 'C', 'El texto combina el valor de los residuos con alteraciones, recuperación, comparación y límites interpretativos.', '{"paragraph":7,"quote":"combine context, recovery technique, measurement, comparison, and uncertainty"}'::jsonb, '{"A":"El segundo párrafo niega que sea una fotografía directa.","B":"Cerámica común e importada pueden aportar información social.","D":"Se usan cribado y flotación para recuperar restos pequeños."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000132'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'Why might a broken vessel not enter a trash deposit immediately?', '[{"id":"A","text":"It always becomes an imported heirloom."},{"id":"B","text":"Floodwater turns it into animal bone."},{"id":"C","text":"Screens prevent pottery from being discarded."},{"id":"D","text":"It may be repaired and used again first."}]'::jsonb, 'D', 'El segundo párrafo ofrece la reparación como etapa previa a la eliminación final.', '{"paragraph":2,"quote":"A cracked vessel may be repaired before it is finally thrown away"}'::jsonb, '{"A":"Un objeto reparado no se vuelve necesariamente importado.","B":"La inundación puede mezclar capas, no transformar materiales.","C":"Las cribas son herramientas de excavación posterior."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000133'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “cluster” in paragraph 5 is closest in meaning to', '[{"id":"A","text":"be concentrated together"},{"id":"B","text":"disappear completely"},{"id":"C","text":"be dated incorrectly"},{"id":"D","text":"float to the surface"}]'::jsonb, 'A', 'Las cerámicas finas aparecen agrupadas alrededor de determinadas casas, señalando una distribución espacial.', '{"paragraph":5,"quote":"may cluster around certain houses"}'::jsonb, '{"B":"La presencia agrupada no implica desaparición.","C":"La frase habla de ubicación, no error cronológico.","D":"Flotar describe restos botánicos en otro procedimiento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000134'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 2, 'Why does the author mention animals carrying bones away?', '[{"id":"A","text":"To prove that animals created all archaeological sites"},{"id":"B","text":"To illustrate how material can move after it is discarded"},{"id":"C","text":"To show that bones cannot reveal diet"},{"id":"D","text":"To explain how pottery was manufactured"}]'::jsonb, 'B', 'El ejemplo forma parte de los procesos que alteran un depósito y deben reconstruirse.', '{"paragraph":2,"quote":"bones may be carried away by animals after disposal"}'::jsonb, '{"A":"Los animales son un agente entre varios.","C":"Los huesos sí aportan evidencia cuando se analizan con contexto.","D":"La fabricación cerámica no se explica."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000135'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 3, 'Why are recovery techniques important when comparing deposits?', '[{"id":"A","text":"Every deposit contains exactly the same objects."},{"id":"B","text":"Floating removes all evidence of plants."},{"id":"C","text":"Different methods can change which small remains are visible and counted."},{"id":"D","text":"Large pottery fragments can be found only in water."}]'::jsonb, 'C', 'Sin cribado o flotación, semillas y huesos diminutos pueden faltar del registro observado y sesgar comparaciones.', '{"paragraph":3,"quote":"can transform an apparently empty sample into evidence"}'::jsonb, '{"A":"Los depósitos varían por actividad y ubicación.","B":"La flotación recupera restos botánicos.","D":"La cerámica grande no depende exclusivamente de flotación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000136'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 3, 'All of the following are suggested for interpreting animal bones EXCEPT', '[{"id":"A","text":"cut marks"},{"id":"B","text":"which body parts are present"},{"id":"C","text":"the animals’ ages"},{"id":"D","text":"the color of nearby modern buildings"}]'::jsonb, 'D', 'El color de edificios modernos no figura entre las variables; las otras se enumeran en el cuarto párrafo.', '{"paragraph":4,"quote":"compare body parts, cut marks, burning, age of animals"}'::jsonb, '{"A":"Las partes ayudan a distinguir procesamiento y consumo.","B":"Las marcas de corte revelan actividad.","C":"La edad de los animales forma parte de la comparación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000137'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 7, 3, 'The word “its” in paragraph 5, in the phrase “extend its use,” refers to', '[{"id":"A","text":"an ordinary vessel"},{"id":"B","text":"an imported house"},{"id":"C","text":"an excavated workshop"},{"id":"D","text":"a cattle bone"}]'::jsonb, 'A', 'El posesivo retoma el objeto reparado —la vasija común— cuya vida útil se prolonga.', '{"paragraph":5,"quote":"repairs on ordinary vessels can indicate efforts to extend their use"}'::jsonb, '{"B":"«Imported» describe cerámica, no casas.","C":"El taller se menciona en relación con huesos.","D":"La reparación descrita corresponde a recipientes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000138'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 8, 3, 'Which statement best expresses the caution in paragraph 5?', '[{"id":"A","text":"Imported ceramics are found only in poor homes."},{"id":"B","text":"Objects associated with wealth are useful clues but do not identify social status with certainty."},{"id":"C","text":"Wealthy households never discard objects."},{"id":"D","text":"Every repaired vessel belonged to the same family."}]'::jsonb, 'B', 'El texto ofrece excepciones —herencias y áreas no excavadas— para evitar equivalencias automáticas.', '{"paragraph":5,"quote":"expensive objects do not map perfectly onto wealthy people"}'::jsonb, '{"A":"La concentración puede asociarse con ciertas casas, sin exclusividad inversa.","C":"Los ricos pueden desechar en lugares no excavados.","D":"Las reparaciones indican uso prolongado, no una familia única."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000139'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'How would the author’s approach to archaeological interpretation best be described?', '[{"id":"A","text":"Certain that one object explains an entire site"},{"id":"B","text":"Dismissive of ordinary household activities"},{"id":"C","text":"Evidence-based and cautious about simple conclusions"},{"id":"D","text":"Focused only on written records"}]'::jsonb, 'C', 'A lo largo del texto se exigen patrones múltiples, contexto y reconocimiento explícito de incertidumbre.', '{"paragraph":7,"quote":"A trash pit cannot tell a household’s whole story"}'::jsonb, '{"A":"Se rechaza depender de un solo conteo.","B":"Las rutinas cotidianas son precisamente el interés.","D":"Los residuos complementan lo que monumentos y registros no celebran."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000140'::uuid, '60000000-0000-4000-8000-000000000023'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'Which description best matches the organization of the passage?', '[{"id":"A","text":"It gives instructions for repairing modern pottery."},{"id":"B","text":"It follows one bone from an animal to a museum."},{"id":"C","text":"It argues that all waste has the same meaning across cultures."},{"id":"D","text":"It presents the value of refuse evidence, then examines successive sources of bias and methods of interpretation."}]'::jsonb, 'D', 'Tras introducir el valor documental, cada párrafo agrega formación, recuperación, cantidad, desigualdad y categorías culturales.', '{"paragraph":7,"quote":"The archaeology of refuse is powerful precisely because it is necessarily incomplete."}'::jsonb, '{"A":"La reparación es un ejemplo histórico, no un manual.","B":"No se narra la trayectoria de un hueso individual.","C":"El sexto párrafo destaca variación cultural del concepto de residuo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000141'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'What is the passage’s central claim about urban sanitation?', '[{"id":"A","text":"Safe water emerged from layered technical and institutional changes that require continued maintenance and equitable reach."},{"id":"B","text":"One scientific discovery immediately made every city’s water safe."},{"id":"C","text":"Sewer construction mattered only because it improved smells."},{"id":"D","text":"Modern systems no longer face contamination risks."}]'::jsonb, 'A', 'El texto integra teoría, evidencia, barreras técnicas, inversión, medición, ambiente y desigualdad persistente.', '{"paragraph":7,"quote":"durable safety depends on maintenance, public institutions, and attention to who remains outside the network"}'::jsonb, '{"B":"La aceptación del agua contaminada no produjo seguridad inmediata.","C":"El olor motivó obras, pero la función sanitaria fue más amplia.","D":"Tuberías viejas y lluvias extremas pueden reabrir riesgos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000142'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'What made neighboring houses useful for comparing disease patterns?', '[{"id":"A","text":"They all used the same private well."},{"id":"B","text":"They could receive water from different companies through separate pipes."},{"id":"C","text":"Their residents never moved."},{"id":"D","text":"They were located outside every city boundary."}]'::jsonb, 'B', 'La variación accidental de proveedores entre viviendas cercanas permitía comparar exposición con otras condiciones similares.', '{"paragraph":2,"quote":"Competing companies sometimes served neighboring houses through different pipes."}'::jsonb, '{"A":"El punto era la diferencia de suministro.","C":"No se afirma inmovilidad de residentes.","D":"Eran viviendas dentro de redes urbanas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000143'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “barrier” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"a political border"},{"id":"B","text":"a source of smell"},{"id":"C","text":"a layer of protection"},{"id":"D","text":"a method of taxation"}]'::jsonb, 'C', 'La desinfección se suma a filtración y tuberías como defensa contra contaminación microbiana.', '{"paragraph":3,"quote":"provided another barrier"}'::jsonb, '{"A":"El contexto es tratamiento de agua, no territorio.","B":"El olor pertenece a teorías anteriores.","D":"Los impuestos financian infraestructura pero no son barrera sanitaria."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000144'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 3, 'Why does the author discuss miasma theory?', '[{"id":"A","text":"To claim that smell is the true cause of every infection"},{"id":"B","text":"To prove that sewers were never constructed"},{"id":"C","text":"To replace evidence about contaminated water"},{"id":"D","text":"To show that an incorrect explanation could still encourage some useful environmental action"}]'::jsonb, 'D', 'Aunque equivocada en transmisión, la preocupación por aire fétido impulsó limpieza y alcantarillado.', '{"paragraph":1,"quote":"That theory was wrong about transmission, but concern about smell still motivated some street cleaning and sewer construction."}'::jsonb, '{"A":"El texto declara incorrecta la teoría causal.","B":"La construcción aparece como consecuencia parcial.","C":"La evidencia sobre agua se desarrolla en el siguiente párrafo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000145'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 3, 'Why could improving only a water intake fail to prevent disease?', '[{"id":"A","text":"Water could be contaminated later through leaking pipes or unmanaged waste."},{"id":"B","text":"Sand filters always added sewage."},{"id":"C","text":"Chemical treatment prevented water from entering pipes."},{"id":"D","text":"Every intake was already far from pollution."}]'::jsonb, 'A', 'El enfoque de barreras múltiples reconoce que el agua limpia en origen puede contaminarse durante distribución.', '{"paragraph":3,"quote":"No single measure was sufficient when distribution pipes still leaked"}'::jsonb, '{"B":"Los filtros reducían material y microbios.","C":"La desinfección protegía y no bloqueaba distribución.","D":"Mover tomas lejos del drenaje era una mejora pendiente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000146'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 3, 'All of the following are mentioned as parts of safer water systems EXCEPT', '[{"id":"A","text":"filtration"},{"id":"B","text":"eliminating every municipal boundary"},{"id":"C","text":"chemical disinfection"},{"id":"D","text":"pressure monitoring"}]'::jsonb, 'B', 'Coordinar entre límites era necesario, pero no se propone eliminarlos; las otras medidas se enumeran.', '{"paragraph":7,"quote":"Filtration, disinfection, sewer separation, monitoring, and watershed protection work together."}'::jsonb, '{"A":"La filtración aparece como barrera física y biológica.","C":"La desinfección química agrega protección.","D":"Los ingenieros seguían presión para rendición de cuentas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000147'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 7, 3, 'The phrase “This shift” in paragraph 6 refers to', '[{"id":"A","text":"moving wealthy residents into informal settlements"},{"id":"B","text":"replacing all laboratories with maps"},{"id":"C","text":"expanding sanitation goals to reduce downstream environmental harm"},{"id":"D","text":"returning to miasma theory"}]'::jsonb, 'C', 'El demostrativo retoma la ampliación desde proteger tomas urbanas hasta tratar las descargas y el río compartido.', '{"paragraph":6,"quote":"This shift required seeing the river"}'::jsonb, '{"A":"La desigualdad urbana se discute, pero no se describe ese traslado.","B":"Mapas y laboratorios son herramientas complementarias.","D":"El pasaje avanza hacia transmisión hídrica, no regresa a miasma."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000148'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 8, 3, 'Which statement best expresses the warning in paragraph 5?', '[{"id":"A","text":"One clean sample proves permanent safety."},{"id":"B","text":"Laboratories make standards unnecessary."},{"id":"C","text":"Only foul-smelling water needs to be tested."},{"id":"D","text":"A testing program can overlook brief risks if its sampling is too limited in time or place."}]'::jsonb, 'D', 'La frecuencia, ubicación y objetivos del muestreo determinan si se detectan episodios cortos.', '{"paragraph":5,"quote":"testing only occasional samples could miss short contamination events"}'::jsonb, '{"A":"Una muestra aislada no cubre variación temporal.","B":"Los estándares orientan lo que los laboratorios deben comprobar.","C":"Microbios peligrosos no dependen necesariamente de olor."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000149'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'How does the author evaluate sanitation progress?', '[{"id":"A","text":"As substantial but vulnerable to neglect and unequal service"},{"id":"B","text":"As a complete failure with no health benefits"},{"id":"C","text":"As permanently finished in every modern city"},{"id":"D","text":"As unrelated to political choices"}]'::jsonb, 'A', 'Se reconocen soluciones acumuladas y beneficios, junto con infraestructura envejecida y exclusión.', '{"paragraph":7,"quote":"can reopen risks that appear solved"}'::jsonb, '{"B":"Los beneficios de salud pública se describen como amplios.","C":"Los riesgos pueden regresar.","D":"Impuestos, límites y poder político afectan implementación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000150'::uuid, '60000000-0000-4000-8000-000000000024'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'How does paragraph 6 broaden the discussion?', '[{"id":"A","text":"It narrows the passage to the smell of one street."},{"id":"B","text":"It extends sanitation from protecting city residents to considering downstream ecosystems and communities."},{"id":"C","text":"It abandons water to discuss railway schedules."},{"id":"D","text":"It argues that rivers should serve only as waste pipes."}]'::jsonb, 'B', 'El párrafo incorpora externalidades ambientales y usuarios aguas abajo al objetivo sanitario.', '{"paragraph":6,"quote":"an ecosystem and a shared resource"}'::jsonb, '{"A":"La escala se amplía más allá de una calle.","C":"El tema sigue siendo agua y residuos.","D":"La metáfora de tubería se rechaza explícitamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000151'::uuid, '60000000-0000-4000-8000-000000000025'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 1, 'Which factor shaped artists’ historical use of blue according to the passage?', '[{"id":"A","text":"A universal ban on blue images"},{"id":"B","text":"The absence of trade between regions"},{"id":"C","text":"The color’s material cost, stability, and chemical behavior"},{"id":"D","text":"A belief that every blue pigment was identical"}]'::jsonb, 'C', 'El texto relaciona disponibilidad, envejecimiento, compatibilidad y simbolismo con decisiones artísticas.', '{"paragraph":3,"quote":"reflects chemistry and trade as much as artistic preference"}'::jsonb, '{"A":"No se menciona una prohibición general.","B":"El lapislázuli viajaba por rutas comerciales.","D":"Los pigmentos tenían propiedades distintas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000152'::uuid, '60000000-0000-4000-8000-000000000025'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'Why was lapis lazuli sometimes reserved for important areas?', '[{"id":"A","text":"It was the only material that faded instantly."},{"id":"B","text":"It could be found beside every workshop."},{"id":"C","text":"It always damaged protective layers."},{"id":"D","text":"It produced a brilliant color but was costly."}]'::jsonb, 'D', 'El primer párrafo vincula el azul brillante con largas rutas y precio elevado.', '{"paragraph":1,"quote":"produced a brilliant blue, but the stone traveled through long trade routes and was expensive"}'::jsonb, '{"A":"El desvanecimiento se asocia a ciertos tintes vegetales.","B":"La distancia comercial contradice disponibilidad local universal.","C":"No se afirma daño inevitable a capas protectoras."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000153'::uuid, '60000000-0000-4000-8000-000000000025'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 1, 'The word “drawbacks” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"disadvantages"},{"id":"B","text":"recipes"},{"id":"C","text":"symbols"},{"id":"D","text":"trade routes"}]'::jsonb, 'A', 'Las oraciones siguientes enumeran problemas de cambio de color y pérdida por luz.', '{"paragraph":2,"quote":"Other blue materials had drawbacks."}'::jsonb, '{"B":"Las recetas intentaban reducir problemas.","C":"El simbolismo es un criterio de elección posterior.","D":"Las rutas explican costo, no el significado de la palabra."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000154'::uuid, '60000000-0000-4000-8000-000000000025'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why would a workshop keep detailed pigment recipes?', '[{"id":"A","text":"Painters were forbidden to observe finished colors."},{"id":"B","text":"Small differences in preparation could affect color and durability."},{"id":"C","text":"All materials behaved the same in every mixture."},{"id":"D","text":"Synthetic pigments existed before mineral pigments."}]'::jsonb, 'B', 'La variabilidad de resultados y compatibilidad vuelve valioso controlar preparación y capas.', '{"paragraph":2,"quote":"Workshops developed careful recipes"}'::jsonb, '{"A":"La observación del resultado era esencial.","C":"El texto destaca reacciones distintas.","D":"Los sintéticos se desarrollaron después."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000155'::uuid, '60000000-0000-4000-8000-000000000025'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 2, 'How did synthetic blues change artistic choice according to the final paragraph?', '[{"id":"A","text":"Synthetic blue ended all artistic use of minerals."},{"id":"B","text":"Painters selected colors only by price."},{"id":"C","text":"New synthetic pigments broadened choices without eliminating the reasons artists might prefer older ones."},{"id":"D","text":"Chemistry became irrelevant after synthetic blue appeared."}]'::jsonb, 'C', 'El cierre presenta una ampliación, no una sustitución total, y conserva múltiples criterios de elección.', '{"paragraph":3,"quote":"did not simply replace older materials"}'::jsonb, '{"A":"El texto niega el reemplazo simple.","B":"Matiz, textura y simbolismo también importaban.","D":"La compatibilidad química siguió siendo un criterio."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000156'::uuid, '60000000-0000-4000-8000-000000000026'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 2, 'What does the author explain about dance notation?', '[{"id":"A","text":"It makes live performance unnecessary."},{"id":"B","text":"It can be understood without any training."},{"id":"C","text":"It records only the names of dancers."},{"id":"D","text":"It records and supports analysis of movement but cannot preserve every performance quality."}]'::jsonb, 'D', 'El pasaje combina usos de preservación y análisis con límites de expresividad y lectura.', '{"paragraph":3,"quote":"a tool for preserving and analyzing selected features"}'::jsonb, '{"A":"La notación complementa, no reemplaza, la actuación.","B":"Los sistemas detallados requieren aprendizaje.","C":"Se registran secuencias, tiempo, espacio y relaciones."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000157'::uuid, '60000000-0000-4000-8000-000000000026'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Which information can dance notation preserve?', '[{"id":"A","text":"Timing and relationships among dancers"},{"id":"B","text":"The exact feelings of every audience member"},{"id":"C","text":"The future cost of a theater"},{"id":"D","text":"The chemical composition of costumes"}]'::jsonb, 'A', 'El primer párrafo enumera secuencias, direcciones, tiempo y relaciones entre intérpretes.', '{"paragraph":1,"quote":"timing, and relationships among dancers"}'::jsonb, '{"B":"La reacción del público no forma parte de la partitura.","C":"Los costos teatrales no se mencionan.","D":"La composición de vestuario no es movimiento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000158'::uuid, '60000000-0000-4000-8000-000000000026'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 3, 2, 'All of the following may supplement written notation EXCEPT', '[{"id":"A","text":"oral coaching"},{"id":"B","text":"water-quality measurements"},{"id":"C","text":"photographs"},{"id":"D","text":"video"}]'::jsonb, 'B', 'El segundo párrafo enumera las tres formas de apoyo; medir agua no pertenece al proceso coreográfico descrito.', '{"paragraph":2,"quote":"combine notation with oral coaching, photographs, or video"}'::jsonb, '{"A":"La enseñanza oral ayuda con interpretación.","C":"Las fotografías conservan posiciones.","D":"El video registra movimiento temporal."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000159'::uuid, '60000000-0000-4000-8000-000000000026'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why might a researcher study a score in addition to a video?', '[{"id":"A","text":"The score contains every quality with no ambiguity."},{"id":"B","text":"Video cannot show movement."},{"id":"C","text":"The score may make structural patterns easier to compare."},{"id":"D","text":"A score eliminates differences between performances."}]'::jsonb, 'C', 'El último párrafo señala que la representación escrita vuelve visibles patrones y facilita comparación entre versiones.', '{"paragraph":3,"quote":"allows researchers to compare versions"}'::jsonb, '{"A":"El pasaje reconoce cualidades no capturadas.","B":"El video sí registra movimiento.","D":"Las diferencias son objeto de comparación, no se eliminan."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000160'::uuid, '60000000-0000-4000-8000-000000000026'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 5, 2, 'The word “it” at the end of paragraph 3 refers to', '[{"id":"A","text":"the researcher"},{"id":"B","text":"the staff"},{"id":"C","text":"oral coaching"},{"id":"D","text":"performance"}]'::jsonb, 'D', 'La notación preserva y analiza características seleccionadas de la actuación.', '{"paragraph":3,"quote":"selected features of it"}'::jsonb, '{"A":"El investigador utiliza la herramienta, pero no es su referente.","B":"El pentagrama es un formato de símbolos.","C":"La enseñanza oral es un complemento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000161'::uuid, '60000000-0000-4000-8000-000000000027'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Which idea about oral epics does the passage emphasize?', '[{"id":"A","text":"Performers recreate a shared tradition through formulas, context, and audience interaction."},{"id":"B","text":"Every performance reproduces a fixed text word for word."},{"id":"C","text":"Repeated language proves that performers have poor memories."},{"id":"D","text":"A single recording contains the complete tradition."}]'::jsonb, 'A', 'El texto cuestiona el modelo de copia fija y explica composición situada y variación artística.', '{"paragraph":4,"quote":"variation is treated as part of the art"}'::jsonb, '{"B":"Las versiones pueden variar mucho.","C":"Las fórmulas apoyan fluidez y planificación.","D":"Una grabación conserva solo una ocasión."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000162'::uuid, '60000000-0000-4000-8000-000000000027'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 2, 2, 'Why does the author discuss formulaic language?', '[{"id":"A","text":"To show that listeners dislike repetition"},{"id":"B","text":"To explain a technique that supports composition during performance"},{"id":"C","text":"To prove that epics have no rhythm"},{"id":"D","text":"To identify errors introduced only by writing"}]'::jsonb, 'B', 'Las frases rítmicas conocidas dan tiempo para planear y ayudan al seguimiento del público.', '{"paragraph":2,"quote":"support fluency and variation"}'::jsonb, '{"A":"La repetición ayuda a los oyentes.","C":"Las fórmulas encajan precisamente en patrones rítmicos.","D":"Funcionan dentro de la actuación oral."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000163'::uuid, '60000000-0000-4000-8000-000000000027'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 3, 2, 'What might cause a performer to shorten a genealogical section?', '[{"id":"A","text":"A ban on local names"},{"id":"B","text":"The absence of any audience"},{"id":"C","text":"Limited time"},{"id":"D","text":"The invention of video"}]'::jsonb, 'C', 'El tercer párrafo contrasta expansión por interés del público con reducción cuando el tiempo escasea.', '{"paragraph":3,"quote":"shorten a genealogical section when time is limited"}'::jsonb, '{"A":"Los nombres locales pueden incorporarse.","B":"El público influye en decisiones.","D":"La grabación se discute después."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000164'::uuid, '60000000-0000-4000-8000-000000000027'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'How can two performances be considered the same epic despite major differences?', '[{"id":"A","text":"They must have exactly the same number of words."},{"id":"B","text":"They are both written by one audience member."},{"id":"C","text":"They exclude all current concerns."},{"id":"D","text":"They draw on shared characters, episodes, and patterns."}]'::jsonb, 'D', 'La identidad reside en recursos narrativos compartidos, mientras longitud y énfasis pueden adaptarse.', '{"paragraph":1,"quote":"known episodes, repeated phrases, rhythmic patterns, and character types"}'::jsonb, '{"A":"La variación verbal es una característica central.","B":"La composición corresponde al intérprete.","C":"Los asuntos actuales pueden entrar en la narración."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000165'::uuid, '60000000-0000-4000-8000-000000000027'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 3, 'How does the author view variation in oral performance?', '[{"id":"A","text":"As a meaningful feature that should be studied rather than corrected away"},{"id":"B","text":"As evidence that every singer is careless"},{"id":"C","text":"As a problem solved completely by transcription"},{"id":"D","text":"As irrelevant to the social setting"}]'::jsonb, 'A', 'El cierre pide comparar versiones y tratar la variación como parte del arte.', '{"paragraph":4,"quote":"rather than as corruption of a perfect text"}'::jsonb, '{"B":"Las fórmulas y adaptaciones son recursos, no descuido.","C":"La transcripción elimina dimensiones de la actuación.","D":"El contexto social es necesario para interpretar cambios."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000166'::uuid, '60000000-0000-4000-8000-000000000028'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'What balance must museums manage according to the passage?', '[{"id":"A","text":"Keeping every gallery completely dark"},{"id":"B","text":"Making objects visible while limiting cumulative light damage"},{"id":"C","text":"Exposing paper to more light than stone"},{"id":"D","text":"Replacing all original objects with lamps"}]'::jsonb, 'B', 'El texto describe daño acumulativo y estrategias para permitir acceso sin agotar la tolerancia del objeto.', '{"paragraph":3,"quote":"balance access with preservation"}'::jsonb, '{"A":"La iluminación es necesaria para ver.","C":"El papel suele ser más sensible.","D":"Las lámparas iluminan objetos, no los sustituyen."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000167'::uuid, '60000000-0000-4000-8000-000000000028'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Why might a museum rotate a fragile work off display?', '[{"id":"A","text":"To increase the ultraviolet radiation it receives"},{"id":"B","text":"To make stone objects fade faster"},{"id":"C","text":"To reduce its total exposure to damaging light"},{"id":"D","text":"To eliminate the need for conservation decisions"}]'::jsonb, 'C', 'La rotación limita el tiempo iluminado y, por tanto, el daño acumulado.', '{"paragraph":2,"quote":"rotate fragile works off display"}'::jsonb, '{"A":"Se eligen lámparas con poca radiación ultravioleta.","B":"La rotación protege la obra frágil, no perjudica piedra.","D":"Es una decisión de conservación, no su eliminación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000168'::uuid, '60000000-0000-4000-8000-000000000028'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 3, 2, 'What does the passage mean by saying that displaying an object “consumes” light exposure?', '[{"id":"A","text":"The object produces electricity for the gallery."},{"id":"B","text":"Light damage can always be reversed later."},{"id":"C","text":"Visitors remove light from the room."},{"id":"D","text":"Each period on display uses part of the object’s lifetime tolerance."}]'::jsonb, 'D', 'El verbo presenta la exposición segura como un presupuesto limitado que disminuye con el tiempo.', '{"paragraph":3,"quote":"consumes part of the limited light exposure"}'::jsonb, '{"A":"No se describe generación eléctrica.","B":"El daño se caracteriza como permanente.","C":"La entrada de visitantes activa luz en algunos casos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000169'::uuid, '60000000-0000-4000-8000-000000000028'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 4, 2, 'Which action is NOT mentioned as a way to reduce harmful exposure?', '[{"id":"A","text":"Heating the gallery to a high temperature"},{"id":"B","text":"using low-ultraviolet lamps"},{"id":"C","text":"limiting brightness"},{"id":"D","text":"installing motion sensors"}]'::jsonb, 'A', 'La temperatura elevada no aparece como estrategia; las otras tres sí se enumeran.', '{"paragraph":2,"quote":"choose lamps that emit little ultraviolet radiation, limit brightness"}'::jsonb, '{"B":"Reducir ultravioleta limita daño.","C":"La intensidad se controla.","D":"Los sensores mantienen penumbra sin visitantes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000170'::uuid, '60000000-0000-4000-8000-000000000028'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 2, 'Why can directed light improve preservation?', '[{"id":"A","text":"It guarantees that no light reaches the object."},{"id":"B","text":"It can make the object readable without brightly lighting the entire room."},{"id":"C","text":"It makes every material equally durable."},{"id":"D","text":"It increases cumulative exposure everywhere."}]'::jsonb, 'B', 'El contraste concentra la luz necesaria y permite bajar el nivel general.', '{"paragraph":2,"quote":"remains legible at a lower overall level"}'::jsonb, '{"A":"El objeto debe recibir algo de luz para verse.","C":"La sensibilidad material sigue variando.","D":"El objetivo es reducir exposición total."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000171'::uuid, '60000000-0000-4000-8000-000000000029'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'What approach to interpreting textile patterns does the passage support?', '[{"id":"A","text":"Assigning one permanent meaning to every motif"},{"id":"B","text":"Ignoring how a textile was made"},{"id":"C","text":"Combining material evidence with cultural context and makers’ knowledge"},{"id":"D","text":"Treating all geometric patterns as accidental"}]'::jsonb, 'C', 'El texto insiste en variación de significados y en integrar análisis técnico, historia oral y práctica viva.', '{"paragraph":4,"quote":"brings material analysis into conversation with oral history"}'::jsonb, '{"A":"Los significados pueden cambiar entre lugares y tiempos.","B":"La estructura técnica aporta información.","D":"Los patrones pueden cumplir funciones técnicas y sociales."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000172'::uuid, '60000000-0000-4000-8000-000000000029'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'How can repeated geometric units assist a weaver?', '[{"id":"A","text":"They remove the need for a loom."},{"id":"B","text":"They guarantee access to imported dyes."},{"id":"C","text":"They prevent anyone from borrowing a motif."},{"id":"D","text":"They can help count threads and maintain tension."}]'::jsonb, 'D', 'El primer párrafo vincula repetición con control del proceso además de ritmo visual.', '{"paragraph":1,"quote":"help maintain tension and count threads"}'::jsonb, '{"A":"El telar condiciona y posibilita la estructura.","B":"Los tintes son un factor social distinto.","C":"Los motivos pueden circular entre comunidades."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000173'::uuid, '60000000-0000-4000-8000-000000000029'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “freeze” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"treat as unchanging"},{"id":"B","text":"make physically cold"},{"id":"C","text":"repair with new thread"},{"id":"D","text":"photograph under bright light"}]'::jsonb, 'A', 'Una etiqueta definitiva puede presentar una tradición flexible como si tuviera un significado inmóvil.', '{"paragraph":3,"quote":"freeze a flexible tradition"}'::jsonb, '{"B":"El contexto es interpretación, no temperatura.","C":"Las reparaciones se detectan mediante estudio técnico.","D":"La fotografía no aparece en esta frase."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000174'::uuid, '60000000-0000-4000-8000-000000000029'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why might contemporary weavers disagree with an older museum label?', '[{"id":"A","text":"Weavers cannot recognize any visual pattern."},{"id":"B","text":"The label may generalize from limited evidence and ignore changing practice."},{"id":"C","text":"Museum labels always describe fiber chemistry only."},{"id":"D","text":"Older textiles contain no cultural information."}]'::jsonb, 'B', 'Basarse en una nota única puede imponer una lectura que los propios creadores usan de otras maneras.', '{"paragraph":3,"quote":"based on a single collector’s note"}'::jsonb, '{"A":"Los tejedores producen y transforman motivos.","C":"Las etiquetas discutidas asignan significados culturales.","D":"El texto valora los textiles como registros complejos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000175'::uuid, '60000000-0000-4000-8000-000000000029'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 1, 5, 3, 'How does the final paragraph relate to the preceding discussion?', '[{"id":"A","text":"It rejects every form of fiber examination."},{"id":"B","text":"It proves that collector notes are always complete."},{"id":"C","text":"It adds scientific material analysis while insisting that it be integrated with cultural knowledge."},{"id":"D","text":"It changes the topic to railway engineering."}]'::jsonb, 'C', 'El cierre amplía las fuentes de evidencia sin permitir que una reemplace a las demás.', '{"paragraph":4,"quote":"These findings do not replace knowledge held by makers."}'::jsonb, '{"A":"Se enumeran fibras, tintes y dirección de hilo como útiles.","B":"El tercer párrafo critica la evidencia única.","D":"El tema continúa siendo interpretación textil."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000176'::uuid, '60000000-0000-4000-8000-000000000030'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 2, 'What does the passage explain about concert-hall acoustics?', '[{"id":"A","text":"Every event requires the longest possible echo."},{"id":"B","text":"Only the performers affect what an audience hears."},{"id":"C","text":"One fixed material creates perfect sound in all rooms."},{"id":"D","text":"Good acoustic design balances reflections differently for different performances."}]'::jsonb, 'D', 'El texto compara usos, materiales, ocupación y elementos móviles para mostrar compromisos acústicos.', '{"paragraph":4,"quote":"a set of trade-offs rather than a single measure of quality"}'::jsonb, '{"A":"La reverberación excesiva puede borrar detalle.","B":"Superficies, forma, asientos y público participan.","C":"Se combinan geometría y materiales ajustables."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000177'::uuid, '60000000-0000-4000-8000-000000000030'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Why does speech generally require acoustic clarity?', '[{"id":"A","text":"Listeners need to distinguish quickly changing consonants."},{"id":"B","text":"Speakers produce no reflected sound."},{"id":"C","text":"Speech is always performed in an empty room."},{"id":"D","text":"Curtains make words travel faster than light."}]'::jsonb, 'A', 'El segundo párrafo da una razón lingüística directa para controlar reverberación en habla.', '{"paragraph":2,"quote":"listeners must distinguish rapid consonants"}'::jsonb, '{"B":"Toda fuente genera sonido directo y reflejado.","C":"La ocupación puede variar.","D":"Las cortinas absorben sonido; no alteran la velocidad de luz."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000178'::uuid, '60000000-0000-4000-8000-000000000030'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 3, 2, 'The phrase “These elements” in paragraph 4 refers to', '[{"id":"A","text":"rapid consonants"},{"id":"B","text":"movable panels, curtains, and overhead reflectors"},{"id":"C","text":"audience members"},{"id":"D","text":"late echoes only"}]'::jsonb, 'B', 'El demostrativo resume los componentes ajustables enumerados en la oración anterior.', '{"paragraph":4,"quote":"movable panels, curtains, or overhead reflectors. These elements"}'::jsonb, '{"A":"Las consonantes motivan claridad pero no son elementos arquitectónicos.","C":"El público absorbe sonido, aunque no es el antecedente inmediato.","D":"Los dispositivos gestionan múltiples reflexiones."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000179'::uuid, '60000000-0000-4000-8000-000000000030'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why might designers test a hall with and without an audience?', '[{"id":"A","text":"Audiences rebuild the ceiling during performances."},{"id":"B","text":"An empty room has no surfaces."},{"id":"C","text":"People absorb sound and can change the room’s reverberation."},{"id":"D","text":"Sound cannot travel when seats are occupied."}]'::jsonb, 'C', 'El tercer párrafo advierte que la absorción del público altera la respuesta respecto de un ensayo vacío.', '{"paragraph":3,"quote":"audiences themselves absorb sound"}'::jsonb, '{"A":"No se atribuye construcción al público.","B":"Paredes, asientos y techo siguen presentes.","D":"El sonido llega por rutas directas y reflejadas."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000180'::uuid, '60000000-0000-4000-8000-000000000030'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 3, 'How should acoustic quality be evaluated according to the final sentence?', '[{"id":"A","text":"A hall should never be adjusted after construction."},{"id":"B","text":"Every room can be perfect for every event."},{"id":"C","text":"Only loudness determines acoustic quality."},{"id":"D","text":"Acoustic quality depends on choices among competing benefits, not one universally best value."}]'::jsonb, 'D', 'La conclusión define el diseño como negociación entre claridad, mezcla, uso y consistencia.', '{"paragraph":4,"quote":"trade-offs rather than a single measure of quality"}'::jsonb, '{"A":"Los paneles y cortinas permiten ajuste.","B":"Se niega perfección universal.","C":"Se analizan tiempo y dirección de reflexiones, no solo volumen."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000181'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'Which principle of restoration is developed throughout the passage?', '[{"id":"A","text":"Intervention requires transparent judgments that balance material stability, appearance, history, and uncertainty."},{"id":"B","text":"Every damaged artwork has one obvious original state."},{"id":"C","text":"The best repair is always completely invisible."},{"id":"D","text":"Digital reconstruction eliminates interpretation."}]'::jsonb, 'A', 'Los ejemplos de limpieza, faltantes, reversibilidad, reparaciones antiguas y modelos digitales exigen decisiones documentadas.', '{"paragraph":7,"quote":"remain honest about uncertainty"}'::jsonb, '{"B":"La intención puede ser incompleta y el envejecimiento complejo.","C":"El cierre rechaza invisibilidad a cualquier costo.","D":"Los modelos también incorporan decisiones."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000182'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'Why can removing varnish threaten an original glaze?', '[{"id":"A","text":"Varnish is always part of the artist’s original paint."},{"id":"B","text":"A solvent may affect both layers when their boundary is uncertain."},{"id":"C","text":"Glaze cannot be examined with samples."},{"id":"D","text":"Darkened surfaces contain no historical evidence."}]'::jsonb, 'B', 'El segundo párrafo vincula límite incierto y acción química del solvente sobre capas distintas.', '{"paragraph":2,"quote":"A solvent strong enough to remove one layer can affect another."}'::jsonb, '{"A":"El barniz puede ser posterior y se distingue del esmalte original.","C":"Se examinan muestras y zonas pequeñas.","D":"Las huellas de edad pueden pertenecer a la historia del objeto."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000183'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “loss” in paragraph 3 is closest in meaning to', '[{"id":"A","text":"a financial expense"},{"id":"B","text":"a forgotten museum address"},{"id":"C","text":"an area where original material is missing"},{"id":"D","text":"a removable varnish"}]'::jsonb, 'C', 'El párrafo contrapone dejar el faltante, rellenarlo y retocarlo dentro de la imagen.', '{"paragraph":3,"quote":"Leaving a loss untouched makes damage visible"}'::jsonb, '{"A":"El contexto es físico, no económico.","B":"No se discute ubicación del museo.","D":"El barniz es una capa, no el vacío de material."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000184'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 3, 'Why does the author discuss retouching visible only at close range?', '[{"id":"A","text":"To show that visitors should never approach art"},{"id":"B","text":"To prove that all missing areas must remain empty"},{"id":"C","text":"To explain why special light damages every pigment"},{"id":"D","text":"To illustrate a compromise between visual continuity and disclosure of modern additions"}]'::jsonb, 'D', 'La técnica permite lectura coherente a distancia y reconocimiento del añadido durante examen.', '{"paragraph":3,"quote":"blends at normal viewing distance but becomes distinguishable under close inspection"}'::jsonb, '{"A":"La distancia sirve para distinguir intervención, no para prohibir acercamiento.","B":"Es una alternativa a dejar vacío.","C":"La luz especial se usa para identificar, no se describe como daño universal."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000185'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 2, 'Why are detailed treatment records valuable even when a repair appears successful?', '[{"id":"A","text":"Future researchers need to know what was changed and why."},{"id":"B","text":"They guarantee that materials will never age."},{"id":"C","text":"They make scientific testing unnecessary."},{"id":"D","text":"They prevent any future reconsideration."}]'::jsonb, 'A', 'Los registros vuelven evaluables las decisiones y permiten reinterpretar con evidencia o tecnología futura.', '{"paragraph":7,"quote":"future researchers can evaluate not only the artwork but the decisions made around it"}'::jsonb, '{"B":"Todos los materiales siguen envejeciendo.","C":"Las pruebas forman parte del registro.","D":"La documentación facilita reconsideración."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000186'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 2, 'All of the following are mentioned as restoration considerations EXCEPT', '[{"id":"A","text":"whether an intervention can be removed"},{"id":"B","text":"increasing the artwork’s auction price"},{"id":"C","text":"the cultural meaning of older repairs"},{"id":"D","text":"the distinction between evidence and speculation"}]'::jsonb, 'B', 'El valor de subasta no aparece como criterio; los otros tres se desarrollan en distintos párrafos.', '{"paragraph":6,"quote":"distinguish evidence from speculation"}'::jsonb, '{"A":"La reversibilidad es un objetivo ético.","C":"Las reparaciones antiguas pueden tener importancia cultural.","D":"Los modelos digitales deben declarar incertidumbre."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000187'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 7, 3, 'The word “it” in paragraph 4, in “the act of removing it,” refers to', '[{"id":"A","text":"the original artist"},{"id":"B","text":"a digital screen"},{"id":"C","text":"a supposedly removable coating"},{"id":"D","text":"the viewing distance"}]'::jsonb, 'C', 'El pronombre retoma el material de recubrimiento cuya eliminación futura puede estresar la superficie.', '{"paragraph":4,"quote":"Even a removable coating may change how an old surface ages, and the act of removing it"}'::jsonb, '{"A":"No se elimina al artista.","B":"La reconstrucción digital aparece después.","D":"La distancia pertenece al retoque del párrafo anterior."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000188'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 8, 3, 'Which statement best expresses the point about old restorations in paragraph 5?', '[{"id":"A","text":"Every older repair must be preserved unchanged."},{"id":"B","text":"Technical accuracy has no importance in conservation."},{"id":"C","text":"Viewers never become familiar with altered works."},{"id":"D","text":"A historically inaccurate addition may itself become part of an artwork’s meaningful history."}]'::jsonb, 'D', 'El texto presenta un conflicto entre revelar material temprano y conservar la biografía posterior del objeto.', '{"paragraph":5,"quote":"technically inaccurate yet culturally important"}'::jsonb, '{"A":"La importancia se evalúa, no produce una regla absoluta.","B":"La exactitud es una consideración entre varias.","C":"La familiaridad generacional es la razón de importancia."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000189'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'How does the author present reversibility?', '[{"id":"A","text":"As a valuable ideal whose practical limits must be acknowledged"},{"id":"B","text":"As an easy guarantee for every material"},{"id":"C","text":"As an outdated idea with no ethical value"},{"id":"D","text":"As a property found only in digital images"}]'::jsonb, 'A', 'El cuarto párrafo valora remover reparaciones futuras pero explica que ninguna acción es perfectamente neutra.', '{"paragraph":4,"quote":"Perfect reversibility is rare"}'::jsonb, '{"B":"Los recubrimientos pueden alterar envejecimiento.","C":"Se denomina objetivo ético.","D":"La discusión se aplica a materiales físicos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000190'::uuid, '60000000-0000-4000-8000-000000000031'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'How does the passage build its argument?', '[{"id":"A","text":"It gives a chronological biography of one painter."},{"id":"B","text":"It examines several restoration decisions and then draws a principle of transparent, documented intervention."},{"id":"C","text":"It lists solvents without discussing ethics."},{"id":"D","text":"It begins by proving that all repairs are reversible."}]'::jsonb, 'B', 'Cada problema concreto contribuye a la síntesis ética del último párrafo.', '{"paragraph":7,"quote":"Good restoration is therefore not measured by making intervention invisible at any cost."}'::jsonb, '{"A":"No se sigue a un artista individual.","C":"Los solventes son un ejemplo dentro de decisiones éticas.","D":"La reversibilidad perfecta se considera rara."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000191'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'What argument does the passage make about historical photographs?', '[{"id":"A","text":"Their physical link to light makes captions unnecessary."},{"id":"B","text":"Every community is represented equally in archives."},{"id":"C","text":"They are valuable evidence whose meaning depends on framing, description, survival, circulation, and ethics."},{"id":"D","text":"A photograph’s meaning remains fixed after exposure."}]'::jsonb, 'C', 'El texto recorre condiciones que median la evidencia visual y concluye con una lectura contextual.', '{"paragraph":7,"quote":"its evidentiary value grows when uncertainty and the history of its use are made visible"}'::jsonb, '{"A":"Los pies de foto orientan y pueden distorsionar.","B":"La supervivencia es selectiva.","D":"Reproducción y nuevas descripciones cambian interpretación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000192'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'Why do some archives preserve earlier versions of captions?', '[{"id":"A","text":"Earlier captions are always more accurate."},{"id":"B","text":"Images cannot be stored without several captions."},{"id":"C","text":"The date of a photograph never matters."},{"id":"D","text":"Caption changes are part of the photograph’s interpretive history."}]'::jsonb, 'D', 'El segundo párrafo propone conservar la evolución descriptiva en vez de hacer pasar el texto actual como eterno.', '{"paragraph":2,"quote":"preserve the history of caption changes"}'::jsonb, '{"A":"Una versión anterior también puede ser inexacta.","B":"La razón es histórica, no una necesidad técnica.","C":"La fecha puede conectar con otros registros."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000193'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “foregrounds” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"emphasizes"},{"id":"B","text":"erases permanently"},{"id":"C","text":"photographs secretly"},{"id":"D","text":"dates precisely"}]'::jsonb, 'A', 'Elegir una categoría dirige la atención hacia determinadas relaciones del grupo.', '{"paragraph":2,"quote":"foregrounds different relationships"}'::jsonb, '{"B":"La clasificación cambia enfoque, no borra necesariamente.","C":"El verbo describe lenguaje de la leyenda.","D":"La fecha es otra información posible."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000194'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 3, 'Why does the author compare an album photograph with a museum print and digital image?', '[{"id":"A","text":"To prove that albums contain no historical evidence"},{"id":"B","text":"To show that scale, setting, and circulation can alter how an image functions"},{"id":"C","text":"To show that digital copies always include more context"},{"id":"D","text":"To identify three cameras used at the same event"}]'::jsonb, 'B', 'El ejemplo introduce transformaciones por reproducción, recorte y publicación reiterada.', '{"paragraph":4,"quote":"Reproduction changes significance."}'::jsonb, '{"A":"El álbum conserva una forma de contexto.","C":"El recorte digital puede eliminar detalles.","D":"Se comparan usos y formatos, no cámaras."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000195'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 3, 'Why can a visually rich archive still give a distorted impression?', '[{"id":"A","text":"Every surviving photograph is false."},{"id":"B","text":"Humidity improves all private collections."},{"id":"C","text":"The processes that preserved photographs favored certain people, events, and institutions."},{"id":"D","text":"Official events were never photographed."}]'::jsonb, 'C', 'La abundancia total no corrige selecciones sistemáticas sobre qué se produjo y sobrevivió.', '{"paragraph":3,"quote":"abundant and still represent some communities or activities poorly"}'::jsonb, '{"A":"La crítica es a representatividad, no autenticidad universal.","B":"La humedad destruyó colecciones.","D":"Los eventos oficiales fueron una prioridad de preservación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000196'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 3, 'All of the following are mentioned as possible effects of reproducing a photograph EXCEPT', '[{"id":"A","text":"changing its scale"},{"id":"B","text":"cropping surrounding details"},{"id":"C","text":"turning it into a symbol"},{"id":"D","text":"restoring every lost collection"}]'::jsonb, 'D', 'La reproducción no recupera archivos desaparecidos; los otros efectos aparecen en el cuarto párrafo.', '{"paragraph":4,"quote":"Repeated publication can turn one image into a symbol"}'::jsonb, '{"A":"Una foto pequeña puede ampliarse.","B":"El recorte elimina contexto.","C":"La repetición puede volverla representativa simbólicamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000197'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 7, 3, 'The phrase “These collaborations” in paragraph 6 refers to', '[{"id":"A","text":"projects in which archives work with communities to add knowledge or guide access"},{"id":"B","text":"contrast adjustments made automatically"},{"id":"C","text":"private decisions that destroyed albums"},{"id":"D","text":"legal rules that forbid all publication"}]'::jsonb, 'A', 'El demostrativo resume identificación, corrección, historia oral y restricciones construidas con participación comunitaria.', '{"paragraph":6,"quote":"These collaborations can add knowledge"}'::jsonb, '{"B":"El ajuste visual pertenece al párrafo anterior.","C":"La pérdida de colecciones no es colaboración.","D":"Se habla de decisiones éticas, no de prohibición universal."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000198'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 8, 3, 'Which statement best expresses the ethical point in paragraph 5?', '[{"id":"A","text":"Any legally published image is ethically harmless."},{"id":"B","text":"Having legal permission does not remove responsibilities toward photographed people and their communities."},{"id":"C","text":"Only photographers can be affected by an image."},{"id":"D","text":"Descendants never have relevant knowledge."}]'::jsonb, 'B', 'El párrafo distingue autorización legal de consentimiento, riesgo, desigualdad y comprensión posterior.', '{"paragraph":5,"quote":"Legal permission to publish does not settle every ethical question"}'::jsonb, '{"A":"La legalidad no agota la ética.","C":"Las personas retratadas pueden sufrir exposición.","D":"Los descendientes pueden interpretar de otra manera."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000199'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'How does the author view community participation in archival description?', '[{"id":"A","text":"As unnecessary because institutions know everything"},{"id":"B","text":"As a method that always creates complete agreement"},{"id":"C","text":"As valuable but not guaranteed to produce one uncontested interpretation"},{"id":"D","text":"As useful only for changing image contrast"}]'::jsonb, 'C', 'Se reconoce conocimiento añadido y, al mismo tiempo, desacuerdo interno.', '{"paragraph":6,"quote":"should not be represented as producing a single collective voice"}'::jsonb, '{"A":"Los archivos pueden carecer de nombres e historias.","B":"El desacuerdo puede permanecer.","D":"La participación se centra en contexto y acceso."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000200'::uuid, '60000000-0000-4000-8000-000000000032'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'What is the function of the final paragraph?', '[{"id":"A","text":"It rejects photographs as evidence."},{"id":"B","text":"It introduces an unrelated history of painting."},{"id":"C","text":"It states that visible details should be ignored."},{"id":"D","text":"It synthesizes the earlier cautions into a method for reading photographs contextually."}]'::jsonb, 'D', 'El cierre reúne autoría, circulación, supervivencia, descripción y voces presentes en una práctica de investigación.', '{"paragraph":7,"quote":"movement between image and context"}'::jsonb, '{"A":"La fotografía conserva valor probatorio.","B":"El tema sigue siendo archivo fotográfico.","C":"Los detalles visibles son una parte de la lectura."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000201'::uuid, '60000000-0000-4000-8000-000000000033'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 1, 'What function of a clock escapement does the passage explain?', '[{"id":"A","text":"It controls stored energy by releasing the gear in regular steps."},{"id":"B","text":"It generates unlimited energy inside the clock."},{"id":"C","text":"It prevents every part from moving."},{"id":"D","text":"It measures temperature without using gears."}]'::jsonb, 'A', 'El texto explica bloqueo, liberación, oscilador y factores que afectan regularidad.', '{"paragraph":1,"quote":"alternately locking and releasing a gear in small, regular steps"}'::jsonb, '{"B":"La energía procede de peso o resorte.","C":"El mecanismo permite movimiento controlado.","D":"La temperatura es una perturbación, no la variable medida."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000202'::uuid, '60000000-0000-4000-8000-000000000033'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 1, 'What produces the familiar ticking sound?', '[{"id":"A","text":"A spring becoming completely unwound at once"},{"id":"B","text":"Repeated contacts as the escapement locks and releases"},{"id":"C","text":"Oil flowing through the clock face"},{"id":"D","text":"The clock measuring outdoor light"}]'::jsonb, 'B', 'El segundo párrafo vincula directamente los contactos repetidos con el sonido.', '{"paragraph":2,"quote":"ticking sound comes from these repeated contacts"}'::jsonb, '{"A":"La liberación libre haría girar y detener rápidamente.","C":"El aceite afecta fricción pero no se describe como origen del tic.","D":"La luz no forma parte del mecanismo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000203'::uuid, '60000000-0000-4000-8000-000000000033'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 1, 'The word “steadiness” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"size"},{"id":"B","text":"brightness"},{"id":"C","text":"regularity"},{"id":"D","text":"cost"}]'::jsonb, 'C', 'La precisión depende de que el oscilador mantenga un período constante.', '{"paragraph":2,"quote":"Accuracy depends on the steadiness of the oscillator"}'::jsonb, '{"A":"Las dimensiones influyen, pero no definen la palabra.","B":"El reloj no produce luz en este contexto.","D":"No se discute precio."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000204'::uuid, '60000000-0000-4000-8000-000000000033'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why would a clock run poorly if its gears were released without an escapement?', '[{"id":"A","text":"The pendulum would create additional energy."},{"id":"B","text":"Temperature would stop affecting metal."},{"id":"C","text":"Every tooth would become larger."},{"id":"D","text":"Its stored energy would be spent too rapidly to mark equal intervals."}]'::jsonb, 'D', 'El contraste inicial explica que la liberación libre hace girar los engranes rápido y agota el sistema.', '{"paragraph":1,"quote":"gears would spin quickly and stop"}'::jsonb, '{"A":"El oscilador regula, no crea energía neta.","B":"La temperatura seguiría afectando componentes.","C":"No se describe crecimiento de dientes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000205'::uuid, '60000000-0000-4000-8000-000000000033'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 2, 'Which statement best expresses the passage’s final point?', '[{"id":"A","text":"Improved clock designs make energy release more uniform rather than producing the energy themselves."},{"id":"B","text":"Modern escapements no longer need moving parts."},{"id":"C","text":"Portable watches are unaffected by motion."},{"id":"D","text":"The main purpose of an escapement is to warm the oil."}]'::jsonb, 'A', 'El cierre distingue la fuente energética de la función reguladora y reconoce perturbaciones reducidas, no eliminadas.', '{"paragraph":3,"quote":"not to create energy but to divide its release into intervals"}'::jsonb, '{"B":"El mecanismo sigue basado en contactos y oscilación.","C":"El movimiento puede perturbar relojes portátiles.","D":"La viscosidad del aceite es un problema, no un objetivo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000206'::uuid, '60000000-0000-4000-8000-000000000034'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 2, 'What distinction does the passage make about open hardware?', '[{"id":"A","text":"Open files guarantee that every device is safe to repair."},{"id":"B","text":"Publishing designs enables study and repair, but practical barriers can remain."},{"id":"C","text":"A parts list is legally identical to a license."},{"id":"D","text":"Open projects never change versions."}]'::jsonb, 'B', 'El texto presenta beneficios informativos y límites físicos, técnicos y legales.', '{"paragraph":3,"quote":"does not guarantee that repair will be easy or safe"}'::jsonb, '{"A":"Se mencionan alta tensión y herramientas especializadas.","C":"Licencias y documentación resuelven problemas distintos.","D":"Declarar versiones es parte de una buena publicación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000207'::uuid, '60000000-0000-4000-8000-000000000034'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Which item may be included in an open hardware project?', '[{"id":"A","text":"A promise that no component will fail"},{"id":"B","text":"A ban on all modifications"},{"id":"C","text":"A circuit layout"},{"id":"D","text":"An unpublished manufacturing secret"}]'::jsonb, 'C', 'El primer párrafo enumera diagramas, circuitos, software, piezas e instrucciones.', '{"paragraph":1,"quote":"circuit layouts"}'::jsonb, '{"A":"La apertura ayuda a detectar fallas, no promete ausencia.","B":"Modificar es uno de los usos permitidos según licencia.","D":"La información esencial se publica."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000208'::uuid, '60000000-0000-4000-8000-000000000034'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 3, 2, 'Why is version information important?', '[{"id":"A","text":"Every version uses exactly the same components."},{"id":"B","text":"Versions replace the need for testing."},{"id":"C","text":"A version number removes high voltage."},{"id":"D","text":"Instructions or replacement parts may apply only to particular revisions."}]'::jsonb, 'D', 'Si diseños evolucionan, identificar la revisión evita aplicar especificaciones incompatibles.', '{"paragraph":1,"quote":"states versions, tolerances, and testing procedures"}'::jsonb, '{"A":"Los cambios entre versiones justifican declararlas.","B":"Las pruebas siguen siendo necesarias.","C":"Los riesgos físicos no desaparecen con metadatos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000209'::uuid, '60000000-0000-4000-8000-000000000034'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 4, 2, 'The word “they” in the final sentence refers to', '[{"id":"A","text":"licenses and practical documentation"},{"id":"B","text":"sealed materials"},{"id":"C","text":"recurring failures"},{"id":"D","text":"replacement components"}]'::jsonb, 'A', 'El pronombre retoma los dos elementos comparados inmediatamente antes.', '{"paragraph":3,"quote":"Both are important, but they solve different problems."}'::jsonb, '{"B":"Los materiales son una barrera física.","C":"Las fallas son información que la comunidad descubre.","D":"Las piezas pueden proponerse a partir de documentación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000210'::uuid, '60000000-0000-4000-8000-000000000034'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 1, 5, 2, 'Which factor is NOT presented as a barrier to practical repair?', '[{"id":"A","text":"specialized tools"},{"id":"B","text":"Users being allowed to read a parts list"},{"id":"C","text":"high voltage"},{"id":"D","text":"components that are no longer available"}]'::jsonb, 'B', 'El acceso a la lista favorece identificación; las otras tres condiciones dificultan reparación.', '{"paragraph":3,"quote":"Specialized tools, high voltage, sealed materials, or unavailable components"}'::jsonb, '{"A":"Herramientas especiales limitan quién puede intervenir.","C":"La alta tensión añade riesgo.","D":"La falta de componentes impide sustitución directa."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000211'::uuid, '60000000-0000-4000-8000-000000000035'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Which idea about cold-chain management is central to the passage?', '[{"id":"A","text":"A final temperature reading reveals every earlier problem."},{"id":"B","text":"Insulation keeps products cold forever without energy."},{"id":"C","text":"Safe delivery depends on continuous monitoring, suitable packaging, and planned responses to interruptions."},{"id":"D","text":"All deviations require automatic disposal."}]'::jsonb, 'C', 'Los párrafos recorren puntos débiles, historial, empaque y decisiones documentadas ante fallas.', '{"paragraph":4,"quote":"combines prevention with documented decisions after an interruption"}'::jsonb, '{"A":"La historia de temperatura es más informativa.","B":"El aislamiento solo ralentiza transferencia.","D":"La decisión depende de magnitud, tiempo y evidencia."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000212'::uuid, '60000000-0000-4000-8000-000000000035'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Why can a loading platform be a weak point?', '[{"id":"A","text":"It records temperature too frequently."},{"id":"B","text":"It always contains excessive insulation."},{"id":"C","text":"It prevents vehicles from arriving."},{"id":"D","text":"Products may warm while waiting outside controlled storage."}]'::jsonb, 'D', 'El primer párrafo usa la espera descubierta como ejemplo de ruptura entre etapas refrigeradas.', '{"paragraph":1,"quote":"warm rapidly while waiting on an uncovered loading platform"}'::jsonb, '{"A":"El problema es falta de control, no exceso de datos.","B":"No se describe aislamiento en la plataforma.","C":"Puede haber espera aunque el vehículo llegue."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000213'::uuid, '60000000-0000-4000-8000-000000000035'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 3, 2, 'Why does the author contrast fixed sensors with package loggers?', '[{"id":"A","text":"To show that measurements at different locations may describe different conditions"},{"id":"B","text":"To argue that warehouses should never be monitored"},{"id":"C","text":"To prove that every package has the same temperature"},{"id":"D","text":"To show that loggers actively cool products"}]'::jsonb, 'A', 'Un sensor ambiental no siempre representa el interior de cada caja; el registrador viajero conserva otra escala de evidencia.', '{"paragraph":2,"quote":"may not represent the temperature inside every package"}'::jsonb, '{"B":"Los sensores fijos siguen siendo útiles.","C":"La variación entre paquetes es precisamente la limitación.","D":"Los registradores miden, no refrigeran."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000214'::uuid, '60000000-0000-4000-8000-000000000035'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why might tightly packed boxes be a problem inside a refrigerated truck?', '[{"id":"A","text":"They make every product freeze instantly."},{"id":"B","text":"They can prevent cooled air from circulating around the load."},{"id":"C","text":"They increase the accuracy of household refrigerators."},{"id":"D","text":"They eliminate all movement damage outside the truck."}]'::jsonb, 'B', 'El tercer párrafo indica que un empaque compacto puede bloquear el flujo necesario para repartir frío.', '{"paragraph":3,"quote":"Packing boxes too tightly can block cold air"}'::jsonb, '{"A":"El bloqueo puede generar zonas cálidas, no congelación universal.","C":"El contexto es transporte, no refrigeración doméstica.","D":"Otros riesgos pueden persistir."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000215'::uuid, '60000000-0000-4000-8000-000000000035'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 3, 'What does the final paragraph say about decisions after a temperature deviation?', '[{"id":"A","text":"Every affected shipment should be accepted."},{"id":"B","text":"Minor changes always make products dangerous."},{"id":"C","text":"They should use recorded evidence to balance waste against safety."},{"id":"D","text":"Only the driver may decide without records."}]'::jsonb, 'C', 'El cierre evita tanto descarte automático como aceptación sin pruebas.', '{"paragraph":4,"quote":"Discarding everything after a minor deviation creates waste, but accepting products without evidence can create health risks."}'::jsonb, '{"A":"La aceptación universal ignora riesgo.","B":"Una desviación menor no implica daño seguro.","D":"El plan define autoridad y usa documentación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000216'::uuid, '60000000-0000-4000-8000-000000000036'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'Why do established keyboard layouts persist according to the passage?', '[{"id":"A","text":"Modern keyboards still use colliding typewriter arms."},{"id":"B","text":"No alternative layout has ever been designed."},{"id":"C","text":"Changing a layout has no training cost."},{"id":"D","text":"Mechanical history and the benefits of a shared learned standard reinforce them."}]'::jsonb, 'D', 'El texto une origen mecánico con dependencia de aprendizaje, fabricación y coordinación.', '{"paragraph":3,"quote":"coordination is valuable"}'::jsonb, '{"A":"Las tecnologías posteriores perdieron esa restricción.","B":"Se mencionan alternativas.","C":"Usuarios y escuelas ya invirtieron en el patrón."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000217'::uuid, '60000000-0000-4000-8000-000000000036'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'What problem could occur when nearby typewriter arms moved quickly?', '[{"id":"A","text":"They could collide or jam."},{"id":"B","text":"They changed the language being typed."},{"id":"C","text":"They erased the inked ribbon."},{"id":"D","text":"They made schools stop teaching."}]'::jsonb, 'A', 'El primer párrafo identifica interferencia física entre brazos como restricción de diseño.', '{"paragraph":1,"quote":"they could collide or jam"}'::jsonb, '{"B":"El mecanismo no modifica el idioma.","C":"La cinta recibe golpes para imprimir.","D":"Las escuelas aparecen en la adopción posterior."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000218'::uuid, '60000000-0000-4000-8000-000000000036'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “imposed” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"measured"},{"id":"B","text":"created"},{"id":"C","text":"removed"},{"id":"D","text":"photographed"}]'::jsonb, 'B', 'Cambiar el estándar generaba un costo de reaprendizaje y compatibilidad.', '{"paragraph":2,"quote":"changing it imposed a cost"}'::jsonb, '{"A":"La evaluación de velocidad es un uso separado.","C":"El costo no desaparecía.","D":"No se trata de imágenes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000219'::uuid, '60000000-0000-4000-8000-000000000036'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why did electronic keyboards retain older layouts after mechanical jams disappeared?', '[{"id":"A","text":"Electronic devices required inked ribbons."},{"id":"B","text":"Every old design was technically perfect."},{"id":"C","text":"Users and institutions had already coordinated around familiar arrangements."},{"id":"D","text":"Manufacturers could not move printed letters."}]'::jsonb, 'C', 'La inversión colectiva en enseñanza, habilidad y equipo creó costo de transición.', '{"paragraph":2,"quote":"network of trained users and established equipment remained"}'::jsonb, '{"A":"La electrónica no depende de cinta mecánica.","B":"El cierre admite estándares imperfectos.","D":"Las teclas pueden reorganizarse técnicamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000220'::uuid, '60000000-0000-4000-8000-000000000036'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 1, 5, 2, 'How does the author view alternative layouts?', '[{"id":"A","text":"They are impossible to learn."},{"id":"B","text":"They should be legally prohibited."},{"id":"C","text":"They guarantee an immediate universal transition."},{"id":"D","text":"They may be useful, but adoption depends on more than technical advantage."}]'::jsonb, 'D', 'El texto reconoce ventajas específicas y explica por qué la coordinación puede frenar un cambio general.', '{"paragraph":3,"quote":"Their existence does not automatically cause a universal switch."}'::jsonb, '{"A":"Pueden aprenderse y servir a necesidades.","B":"No se propone prohibición.","C":"La transición automática se niega."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000221'::uuid, '60000000-0000-4000-8000-000000000037'::uuid, '50000000-0000-4000-8000-000000000002'::uuid, 1, 1, 2, 'What does the passage explain about weather satellites?', '[{"id":"A","text":"They provide broad observations through several instruments that must be interpreted and calibrated with other evidence."},{"id":"B","text":"They directly measure every weather quantity without models."},{"id":"C","text":"Visible satellite images work equally well without sunlight."},{"id":"D","text":"One orbit supplies continuous detail everywhere."}]'::jsonb, 'A', 'El texto cubre órbitas, bandas, procesamiento, modelos y límites para construir una visión integrada.', '{"paragraph":4,"quote":"combined with—not substituted for—other independent scientific evidence"}'::jsonb, '{"B":"Muchas cantidades se infieren.","C":"La banda visible depende de luz diurna.","D":"Las órbitas ofrecen compromisos entre frecuencia y detalle."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000222'::uuid, '60000000-0000-4000-8000-000000000037'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'Which type of measurement can be used at night to estimate cloud-top temperature?', '[{"id":"A","text":"Visible reflected light"},{"id":"B","text":"Infrared radiation"},{"id":"C","text":"A printed color scale alone"},{"id":"D","text":"Mechanical typewriter motion"}]'::jsonb, 'B', 'El segundo párrafo distingue visible diurno de infrarrojo térmico disponible de noche.', '{"paragraph":2,"quote":"Infrared measurements estimate temperatures of cloud tops or surfaces and work at night."}'::jsonb, '{"A":"La imagen visible necesita luz solar.","C":"La escala representa datos, no es sensor.","D":"El teclado no participa en meteorología."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000223'::uuid, '60000000-0000-4000-8000-000000000037'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 1, 3, 2, 'The word “Others” in paragraph 1 refers to', '[{"id":"A","text":"remote ground stations"},{"id":"B","text":"broad ocean regions"},{"id":"C","text":"satellites in lower orbits that pass over different places"},{"id":"D","text":"infrared color scales"}]'::jsonb, 'C', 'El término contrasta dos grupos de satélites: los casi estacionarios y los de órbita más baja.', '{"paragraph":1,"quote":"Others orbit closer to Earth"}'::jsonb, '{"A":"Las estaciones son otra fuente de medición.","B":"Las regiones son observadas, no orbitan.","D":"Las escalas aparecen después."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000224'::uuid, '60000000-0000-4000-8000-000000000037'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why do forecasters examine several channels?', '[{"id":"A","text":"Every channel contains exactly the same information."},{"id":"B","text":"Combining channels stops instruments from aging."},{"id":"C","text":"A visible image already measures ocean wind directly at night."},{"id":"D","text":"Different wavelengths reveal different properties and reduce ambiguity."}]'::jsonb, 'D', 'La variedad de bandas y la conversión de color exige contrastar señales antes de atribuir significado.', '{"paragraph":3,"quote":"compare several channels and ground observations"}'::jsonb, '{"A":"Cada banda responde a propiedades distintas.","B":"El envejecimiento requiere calibración.","C":"La banda visible depende del sol y otras bandas infieren viento."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000225'::uuid, '60000000-0000-4000-8000-000000000037'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 1, 5, 3, 'How does the conclusion evaluate satellite evidence?', '[{"id":"A","text":"Satellite coverage is powerful when it complements models and measurements from other sources."},{"id":"B","text":"Satellites make ground observations obsolete."},{"id":"C","text":"Calibration is needed only before launch."},{"id":"D","text":"Indirect measurements have no scientific value."}]'::jsonb, 'A', 'El cierre valora alcance y repetición, condicionados por calibración e integración.', '{"paragraph":4,"quote":"combined with—not substituted for—other independent scientific evidence"}'::jsonb, '{"B":"La evidencia terrestre se compara continuamente.","C":"Los instrumentos envejecen y se recalibran.","D":"La inferencia es útil cuando se valida."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000226'::uuid, '60000000-0000-4000-8000-000000000038'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 2, 'What does the passage emphasize about river sensors?', '[{"id":"A","text":"They make laboratory samples unnecessary."},{"id":"B","text":"Their frequent data are useful only with maintenance, representative placement, and context."},{"id":"C","text":"Every unusual value indicates a toxic spill."},{"id":"D","text":"A single bank sensor represents an entire river."}]'::jsonb, 'B', 'El texto combina ventaja temporal con ensuciamiento, calibración, ubicación y comunicación.', '{"paragraph":4,"quote":"pair measurements with thresholds, explanations, uncertainty"}'::jsonb, '{"A":"Las muestras de laboratorio complementan.","C":"La turbidez por tormenta tiene otra interpretación.","D":"La posición puede sesgar representatividad."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000227'::uuid, '60000000-0000-4000-8000-000000000038'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 2, 'What can frequent sensor records reveal that monthly sampling may miss?', '[{"id":"A","text":"The legal ownership of every riverbank"},{"id":"B","text":"The manufacturing history of the sensor"},{"id":"C","text":"A short muddy pulse following rainfall"},{"id":"D","text":"A permanent absence of daily cycles"}]'::jsonb, 'C', 'El primer párrafo da el evento breve posterior a lluvia como ejemplo directo.', '{"paragraph":1,"quote":"a muddy pulse after rain"}'::jsonb, '{"A":"La propiedad no es una variable de calidad medida.","B":"La fabricación no se infiere del agua.","D":"Los registros revelan, no eliminan, ciclos diarios."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000228'::uuid, '60000000-0000-4000-8000-000000000038'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 2, 'The word “drift” in paragraph 2 is closest in meaning to', '[{"id":"A","text":"move downstream as a boat"},{"id":"B","text":"become perfectly calibrated"},{"id":"C","text":"display a storm explanation"},{"id":"D","text":"change gradually away from accurate values"}]'::jsonb, 'D', 'La deriva electrónica aparece junto con suciedad y envejecimiento como fuente progresiva de error.', '{"paragraph":2,"quote":"Electronic components drift"}'::jsonb, '{"A":"El sujeto son componentes, no una embarcación.","B":"La calibración corrige la deriva.","C":"Las explicaciones pertenecen al tablero público."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000229'::uuid, '60000000-0000-4000-8000-000000000038'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 4, 2, 'Why are implausibly constant values suspicious?', '[{"id":"A","text":"A failed or fouled sensor may stop responding to real environmental variation."},{"id":"B","text":"Rivers naturally have no variation."},{"id":"C","text":"Reference standards always produce random numbers."},{"id":"D","text":"Constant readings prove the battery is fully charged."}]'::jsonb, 'A', 'Como el río muestra ciclos y eventos, una línea artificialmente plana puede revelar bloqueo o falla.', '{"paragraph":2,"quote":"inspect patterns for sudden jumps or implausibly constant values"}'::jsonb, '{"B":"El primer párrafo destaca cambios diarios.","C":"Los estándares sirven para comparar precisión.","D":"La batería débil es una causa posible de falla, no se descarta por constancia."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000230'::uuid, '60000000-0000-4000-8000-000000000038'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 5, 3, 'Why does the author contrast storm turbidity with a toxic spill?', '[{"id":"A","text":"To claim that storms never affect rivers"},{"id":"B","text":"To illustrate why public measurements need interpretation and context"},{"id":"C","text":"To show that turbidity sensors measure no real property"},{"id":"D","text":"To prove that every dashboard should hide unusual events"}]'::jsonb, 'B', 'Valores superficiales parecidos pueden tener causas y riesgos diferentes, por lo que se necesitan explicaciones.', '{"paragraph":4,"quote":"a number without context may cause confusion"}'::jsonb, '{"A":"La lluvia puede elevar turbidez.","C":"La turbidez es una variable válida.","D":"Se propone explicar y ofrecer contacto, no ocultar."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000231'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'What is the central argument of the passage?', '[{"id":"A","text":"A printing press produced books without human labor."},{"id":"B","text":"Every copy from one edition was perfectly identical."},{"id":"C","text":"Repeatable printing resulted from coordinated materials, labor, machinery, and markets rather than the press alone."},{"id":"D","text":"Writing ink always worked well on metal type."}]'::jsonb, 'C', 'Cada párrafo añade una parte del sistema y el cierre explica reproducción junto con variación.', '{"paragraph":1,"quote":"depended on a larger technical system"}'::jsonb, '{"A":"Compositores, correctores y otros trabajadores eran esenciales.","B":"Se conservan correcciones y diferencias entre copias.","D":"La tinta de escritura podía ser demasiado fluida."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000232'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'Why was consistent type height important?', '[{"id":"A","text":"It determined which books governments censored."},{"id":"B","text":"It made every sheet equally moist."},{"id":"C","text":"It eliminated the need for spacing."},{"id":"D","text":"Uneven pieces would produce letters with different darkness or no clear impression."}]'::jsonb, 'D', 'El segundo párrafo relaciona altura física con contacto uniforme sobre papel.', '{"paragraph":2,"quote":"some letters printed darkly while others barely touched the paper"}'::jsonb, '{"A":"La censura pertenece a economía y política.","B":"La humedad era propiedad del papel.","C":"Los espacios requerían piezas en la forma."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000233'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “body” in paragraph 4 is closest in meaning to', '[{"id":"A","text":"thickness or consistency"},{"id":"B","text":"human figure"},{"id":"C","text":"main text of a law"},{"id":"D","text":"group of readers"}]'::jsonb, 'A', 'La tinta debía permanecer sobre el relieve y transferirse sin escurrir ni extenderse demasiado.', '{"paragraph":4,"quote":"needed enough body to transfer a clear image"}'::jsonb, '{"B":"El contexto es material, no anatomía.","C":"No se habla de contenido jurídico.","D":"Los lectores aparecen en distribución, no en la tinta."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000234'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 2, 'Why does the author mention blank pieces inside a page form?', '[{"id":"A","text":"To prove that blank pages were more valuable than printed ones"},{"id":"B","text":"To show that nonprinting components were necessary to organize and secure printable type"},{"id":"C","text":"To explain why compositors did not read"},{"id":"D","text":"To show that letters were carved directly into paper"}]'::jsonb, 'B', 'Los blancos crean espacios y mantienen la forma aunque no dejan tinta.', '{"paragraph":3,"quote":"blank pieces that created spaces and held the structure tightly together"}'::jsonb, '{"A":"Su función era estructural, no aumentar valor de páginas vacías.","C":"Los compositores leían mientras armaban.","D":"Las letras metálicas se colocaban antes de imprimir."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000235'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 3, 'Why might two copies from the same edition contain different errors?', '[{"id":"A","text":"Every copy used a different alphabet."},{"id":"B","text":"Paper automatically rewrote the text after binding."},{"id":"C","text":"Corrections could be made while the print run was already in progress."},{"id":"D","text":"Printers never examined proofs."}]'::jsonb, 'C', 'Si se detuvo y corrigió la forma tras imprimir algunas hojas, los ejemplares anteriores conservan otro estado.', '{"paragraph":5,"quote":"different corrections made during printing"}'::jsonb, '{"A":"El mismo conjunto de caracteres servía al tiraje.","B":"El papel no altera palabras por sí solo.","D":"La corrección de pruebas se menciona expresamente."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000236'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 3, 'All of the following could introduce variation into printed books EXCEPT', '[{"id":"A","text":"differences in paper moisture"},{"id":"B","text":"type shifting during production"},{"id":"C","text":"corrections made during the run"},{"id":"D","text":"a guarantee that materials never changed"}]'::jsonb, 'D', 'La invariabilidad garantizada no se describe; las otras fuentes de variación aparecen explícitamente.', '{"paragraph":7,"quote":"material variation, correction, binding, and later use"}'::jsonb, '{"A":"El papel variaba en humedad.","B":"El tipo podía desplazarse.","C":"Las correcciones creaban estados distintos."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000237'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 7, 3, 'The phrase “the structure” in paragraph 3 refers to', '[{"id":"A","text":"the locked arrangement of type and spacing pieces"},{"id":"B","text":"the market for unsold books"},{"id":"C","text":"a government censorship office"},{"id":"D","text":"the metal alloy before casting"}]'::jsonb, 'A', 'Las piezas en blanco sostienen físicamente la forma de página ya compuesta.', '{"paragraph":3,"quote":"held the structure tightly together"}'::jsonb, '{"B":"El mercado se discute más tarde.","C":"La censura no forma parte de la página.","D":"La aleación produce tipos individuales antes de su montaje."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000238'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 8, 3, 'Which statement best expresses paragraph 6?', '[{"id":"A","text":"Technical ability guaranteed that every manuscript found readers."},{"id":"B","text":"Production costs and institutional relationships influenced which texts were printed and sold."},{"id":"C","text":"Long print runs always sold out."},{"id":"D","text":"Booksellers had no role in publication."}]'::jsonb, 'B', 'El párrafo une costo inicial, riesgo de inventario, colaboración, privilegios y censura.', '{"paragraph":6,"quote":"Technical capacity did not by itself determine what reached readers."}'::jsonb, '{"A":"El acceso al equipo no asegura publicación o demanda.","C":"Los libros no vendidos inmovilizaban capital.","D":"Los libreros son uno de los actores enumerados."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000239'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'How does the author treat the idea of identical printed copies?', '[{"id":"A","text":"As completely accurate in every detail"},{"id":"B","text":"As impossible because no text was repeated"},{"id":"C","text":"As broadly useful but too simple to describe material variation between copies"},{"id":"D","text":"As irrelevant to printing history"}]'::jsonb, 'C', 'El cierre reconoce consistencia comparativa y luego enumera fuentes de individualidad.', '{"paragraph":7,"quote":"comparatively consistent copies, yet it did not produce perfect uniformity"}'::jsonb, '{"A":"La uniformidad perfecta se niega.","B":"La reproducción de texto sí fue poderosa.","D":"Las diferencias son parte de la explicación histórica."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000240'::uuid, '60000000-0000-4000-8000-000000000039'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'How is the printing passage organized?', '[{"id":"A","text":"It presents a biography of one author."},{"id":"B","text":"It compares only two kinds of paper."},{"id":"C","text":"It begins with censorship and never discusses machinery."},{"id":"D","text":"It moves through components and stages of production before considering economics and overall consequences."}]'::jsonb, 'D', 'La secuencia recorre tipo, composición, tinta, errores, mercado y síntesis.', '{"paragraph":7,"quote":"Understanding printing as a system"}'::jsonb, '{"A":"No hay personaje biográfico central.","B":"El papel es una variable entre muchas.","C":"La maquinaria y los materiales ocupan la mayor parte."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000241'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000001'::uuid, 1, 1, 3, 'What main idea does the passage develop about microgrids?', '[{"id":"A","text":"Independent operation requires coordinated controls, resources, priorities, safety, and long-term support."},{"id":"B","text":"Solar panels alone guarantee unlimited island operation."},{"id":"C","text":"A microgrid must remain permanently disconnected."},{"id":"D","text":"Maintenance becomes unnecessary after one successful test."}]'::jsonb, 'A', 'El pasaje expande islanding desde hardware hacia control, energía, decisiones, seguridad y sostenibilidad institucional.', '{"paragraph":7,"quote":"depends on more than whether it survives one demonstration"}'::jsonb, '{"B":"La separación exige más que paneles.","C":"Normalmente puede intercambiar con la red.","D":"El cierre exige mantenimiento y capacitación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000242'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000004'::uuid, 1, 2, 3, 'What function must local controls assume after islanding?', '[{"id":"A","text":"Creating unlimited battery capacity"},{"id":"B","text":"Stabilizing voltage and frequency"},{"id":"C","text":"Writing fuel contracts automatically"},{"id":"D","text":"Turning every load into a generator"}]'::jsonb, 'B', 'El segundo párrafo explica que esa referencia deja de venir de la red grande.', '{"paragraph":2,"quote":"local controls must perform that task"}'::jsonb, '{"A":"La capacidad energética sigue limitada.","C":"Los contratos son una necesidad institucional.","D":"Las cargas consumen energía aunque algunas se desconecten."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000243'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000009'::uuid, 1, 3, 3, 'The word “shed” in paragraph 4 is closest in meaning to', '[{"id":"A","text":"predict"},{"id":"B","text":"repair"},{"id":"C","text":"disconnect"},{"id":"D","text":"synchronize"}]'::jsonb, 'C', 'Para conservar cargas prioritarias, el control corta temporalmente otras.', '{"paragraph":4,"quote":"Automated controls can shed loads quickly"}'::jsonb, '{"A":"Los pronósticos se usan para renovables.","B":"Reparar no reduce demanda inmediata.","D":"Sincronizar se aplica al reconectar redes."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000244'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000007'::uuid, 1, 4, 2, 'Why does the author give the example of a hospital?', '[{"id":"A","text":"To prove that offices never use electricity"},{"id":"B","text":"To show that batteries work only in hospitals"},{"id":"C","text":"To identify a load that must always be disconnected"},{"id":"D","text":"To illustrate how limited power requires ranking loads by importance"}]'::jsonb, 'D', 'La selección entre urgencias y oficinas concreta decisiones de prioridad durante operación limitada.', '{"paragraph":4,"quote":"classify loads by priority"}'::jsonb, '{"A":"Las oficinas consumen pero pueden ser menos prioritarias.","B":"El almacenamiento sirve en múltiples microredes.","C":"Las áreas clínicas se mantienen, no se desconectan siempre."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000245'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000006'::uuid, 1, 5, 3, 'Why is battery power alone not always sufficient during a long outage?', '[{"id":"A","text":"Its stored energy may be depleted before generation or demand recovers."},{"id":"B","text":"A battery cannot change output rapidly."},{"id":"C","text":"Clouds immediately damage every battery."},{"id":"D","text":"Storage increases every load automatically."}]'::jsonb, 'A', 'El texto distingue respuesta rápida de duración limitada y plantea generadores o reducción de carga.', '{"paragraph":3,"quote":"Several hours of cloudy weather or high demand can exhaust it"}'::jsonb, '{"B":"La rapidez es precisamente una ventaja.","C":"Las nubes reducen solar, no destruyen batería.","D":"El almacenamiento no crea demanda por sí mismo."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000246'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000005'::uuid, 2, 6, 3, 'All of the following are mentioned as inputs to microgrid control decisions EXCEPT', '[{"id":"A","text":"weather forecasts"},{"id":"B","text":"the color of the control-room walls"},{"id":"C","text":"battery charge"},{"id":"D","text":"expected demand"}]'::jsonb, 'B', 'El color del edificio no se usa; las otras variables aparecen en el quinto párrafo.', '{"paragraph":5,"quote":"weather predictions, current battery charge, expected demand, and fuel availability"}'::jsonb, '{"A":"El clima ayuda a anticipar renovables.","C":"La carga disponible condiciona reserva.","D":"La demanda prevista guía almacenamiento y uso."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000247'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000010'::uuid, 2, 7, 3, 'The phrase “the two systems” in paragraph 6 refers to', '[{"id":"A","text":"solar and wind forecasts"},{"id":"B","text":"emergency rooms and offices"},{"id":"C","text":"the islanded microgrid and the utility network"},{"id":"D","text":"fuel contracts and training"}]'::jsonb, 'C', 'Antes de cerrar el interruptor se alinean fase y frecuencia de la red local y externa.', '{"paragraph":6,"quote":"Controls synchronize the two systems first."}'::jsonb, '{"A":"Los pronósticos son entradas del controlador.","B":"Las áreas son cargas dentro del hospital.","D":"Los contratos y formación apoyan operación."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000248'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000011'::uuid, 2, 8, 3, 'Which statement best expresses the reserve point in paragraph 5?', '[{"id":"A","text":"Forecasts must be perfectly accurate for any microgrid to work."},{"id":"B","text":"Renewable output never changes."},{"id":"C","text":"Reserve means disconnecting every critical load."},{"id":"D","text":"Uncertain forecasts are manageable when the system keeps enough flexible capacity."}]'::jsonb, 'D', 'El pasaje no exige predicción perfecta; exige margen para absorber error.', '{"paragraph":5,"quote":"A forecast error does not necessarily cause failure if the system retains adequate reserve."}'::jsonb, '{"A":"La reserva reduce dependencia de exactitud total.","B":"Solar y viento varían.","C":"Las cargas críticas se priorizan."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000249'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000008'::uuid, 2, 9, 3, 'How does the author evaluate technologically advanced microgrids?', '[{"id":"A","text":"Their value is conditional on maintainability, security, affordability, and trained operation."},{"id":"B","text":"The most complex design is always the most resilient."},{"id":"C","text":"Institutional support has no technical relevance."},{"id":"D","text":"One demonstration proves permanent reliability."}]'::jsonb, 'A', 'El cierre cuestiona evaluar solo desempeño inicial o sofisticación.', '{"paragraph":7,"quote":"may provide less resilience than a simpler design supported by durable local institutions"}'::jsonb, '{"B":"La complejidad puede exceder capacidad local.","C":"Las instituciones determinan mantenimiento y operación.","D":"Se exige desempeño sostenido."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true),
    ('70000000-0000-4000-8000-000000000250'::uuid, '60000000-0000-4000-8000-000000000040'::uuid, '50000000-0000-4000-8000-000000000003'::uuid, 2, 10, 3, 'How does the passage progress?', '[{"id":"A","text":"It lists electrical prices in several countries."},{"id":"B","text":"It defines islanding, explains operational requirements, and ends with conditions for durable resilience."},{"id":"C","text":"It describes only solar-panel manufacturing."},{"id":"D","text":"It argues that reconnection needs no safety procedure."}]'::jsonb, 'B', 'La estructura va de concepto y control a almacenamiento, prioridades, pronóstico, reconexión y sostenibilidad.', '{"paragraph":7,"quote":"The value of a microgrid depends on more"}'::jsonb, '{"A":"No hay comparación de tarifas nacionales.","C":"La generación solar es una parte del sistema.","D":"El sexto párrafo exige sincronización y advertencias."}'::jsonb, 'published', 1, 'Contenido original Macitta; revisión lingüística, factual y de fairness v1.', true, true)
on conflict (id) do update
set passage_id = excluded.passage_id,
    primary_skill_id = excluded.primary_skill_id,
    block_index = excluded.block_index,
    order_index = excluded.order_index,
    difficulty = excluded.difficulty,
    prompt = excluded.prompt,
    options = excluded.options,
    correct_option_id = excluded.correct_option_id,
    explanation_es = excluded.explanation_es,
    evidence = excluded.evidence,
    distractor_rationales = excluded.distractor_rationales,
    status = excluded.status,
    content_version = excluded.content_version,
    source_note = excluded.source_note,
    linguistic_reviewed = excluded.linguistic_reviewed,
    fairness_reviewed = excluded.fairness_reviewed,
    updated_at = now();

do $catalog_assertions$
declare
    domain_count integer;
    skill_count integer;
    passage_count integer;
    question_count integer;
    long_count integer;
    invalid_count integer;
begin
    select count(*) into domain_count from public.reading_domains;
    select count(*) into skill_count from public.reading_skills where is_active;
    select count(*) into passage_count
    from public.reading_passages
    where status = 'published' and content_version = 1;
    select count(*) into question_count
    from public.reading_questions
    where status = 'published' and content_version = 1;
    select count(*) into long_count
    from public.reading_passages
    where status = 'published' and length_band = 'long' and content_version = 1;
    select count(*) into invalid_count
    from public.reading_passages p
    left join lateral (
        select count(*) as question_count
        from public.reading_questions q
        where q.passage_id = p.id and q.status = 'published'
    ) counts on true
    where p.status = 'published'
      and (
          not p.linguistic_reviewed
          or not p.factual_reviewed
          or not p.fairness_reviewed
          or (p.length_band = 'long' and counts.question_count <> 10)
          or (p.length_band <> 'long' and counts.question_count <> 5)
      );

    if domain_count < 4
       or skill_count < 11
       or passage_count < 40
       or question_count < 250
       or long_count < 10
       or invalid_count <> 0 then
        raise exception 'Reading catalog assertion failed: domains %, skills %, passages %, questions %, long %, invalid %',
            domain_count, skill_count, passage_count, question_count, long_count, invalid_count;
    end if;
end;
$catalog_assertions$;

commit;
